	function dateformate($str,$value){
		$sty= strpos($str,'yyyy');
		$std= strpos($str,'dd');
		$stm= strpos($str,'mm');
		$value = substr($value,$sty,4).'-'.substr($value,$stm,2).'-'.substr($value,$std,2);
		return $value;
	}
