		$role_id = $post['role'];
		$whr =  "role_id = '".$role_id."'";
		$query=$callConfig->selectQuery(TBL_ROLE_PERMISSIONS,'id,table_name',$whr,'','','');
		//echo $query;
		$tables = $callConfig->getAllRows($query);
		foreach ($tables as  $table) {
			$role_tables[] = $table->table_name;
			$roledata[$table->table_name] = $table->id;
