	function togetitemvalues($item_d){
		global $callConfig;
		if($item_d !=""){
			$whr="id='".$item_d."'" ;
			$query=$callConfig->selectQuery(TBL_ITEMS,'*',$whr,'','','');
			$data = $callConfig->getRow($query);
			if($data->company_id !=""){
				$sosql = "SELECT sum(si.pending_qty) as pending_qty FROM sales_orders so, so_items si WHERE so.company_id = '".$data->company_id."' AND so.company_id = si.company_id AND so.id = si.transaction_id AND so.current_status ='".ST_APPROVED."' AND si.item_id = '".$item_d."' AND so.is_active = si.is_active AND so.is_active = 0";	
				$sores = $callConfig->getRow($sosql);
				
				$data->sales_order_qty = $sores->pending_qty !=""?$sores->pending_qty:0;

				$posql = "SELECT sum(si.pending_qty) as pending_qty FROM purchase_orders so, po_items si WHERE so.company_id = '".$data->company_id."' AND so.company_id = si.company_id AND so.id = si.transaction_id AND so.current_status ='".ST_APPROVED."' AND si.item_id = '".$item_d."' AND so.is_active = si.is_active AND so.is_active = 0";	
				$pores = $callConfig->getRow($posql);	

				$configsql = "SELECT id , default_inventory_account FROM config where company_id = '".$data->company_id."'";
				$configres = $callConfig->getRow($configsql);
				if(isset($configres->default_inventory_account)){
					$data->config_inventory_asset_account = $configres->default_inventory_account;
				}
				$isbsql = "SELECT closing_qty,balance_date FROM `item_st_balances` WHERE company_id = '".$callConfig->company_id."' AND item_id = '".$item_d."' ORDER BY balance_date DESC limit 1";
				$isbres = $callConfig->getRow($isbsql);
				if($isbres->closing_qty !=""){
					$data->stock_in_hand = $isbres->closing_qty !=""?$isbres->closing_qty:0;
				}
				if($isbres->balance_date !=""){
					$data->balance_date = $isbres->balance_date !=""?$isbres->balance_date:0;
				}
				if($isbres->pending_qty !=""){
					$data->purchase_order_qty = $pores->pending_qty !=""?$pores->pending_qty:0;
					if($isbres->pending_qty !=""){
						$available_qty = ($isbres->closing_qty + $pores->pending_qty)-$sores->pending_qty;
					}
				}else{
					$data->purchase_order_qty = 0;
				}
				
				$data->available_qty = $available_qty !=""?$available_qty:0;

				
				if($data->category_id !=""){
					$icsql = "SELECT id , inventory_asset_account, inventory_adjustment_account, inventory_cost_variance_account, cogs_account, purchase_expense_account, sales_revenue_account, sales_discount_account, sales_return_account, purchase_price_variance_account, freight_expense_account, packaging_expense_account, sales_tax_payable_account, purchase_tax_payable_account, promotions_and_discounts_account, sales_allowances_account, deferred_revenue_account, ap_account, ar_account, accrued_expenses_account, prepaid_expenses_account, wip_asset_account, goods_received_not_invoiced_account, invoiced_not_received_account FROM item_categories where id = '".$data->category_id."' AND company_id = '".$data->company_id."' AND is_active = 0";
					$icategory = $callConfig->getRow($icsql);
					$data->item_cat_inventory_asset_account = $icategory->inventory_asset_account;
					$data->item_cat_goods_received_not_invoiced_accountt = $icategory->goods_received_not_invoiced_account;
				} 
			}
			
			if($data->hsn_and_sac_code_id !=""){
				$sql = "SELECT id , code, gst, code_description FROM `hsn_and_sac_codes` where id = '".$data->hsn_and_sac_code_id."'";
				$data2 = $callConfig->getRow($sql);
				$data->hsn_code_id = $data2->id;
				$data->hsn_code = $data2->code;		
				$data->hsn_code_description = $data2->code_description;
				$data->igst = $data2->gst;
			}
		}
		return $data;
	}
