		$row = $callConfig->getRow($query1);
		if($row->id !=''){
			if($post['out_qty']!=0 ){
				$this->itemlifoupdates($post);
			}else{
				$whr21="item_id = '".$post['item_id']."' AND document_type='".$post['document_type']."' AND document_no='".$post['document_no']."'";
