    function toGetFrequencyDate($fdate, $frequency){
    	global $callConfig; 
    	$days = 30/$frequency;
    	//echo $days;
    	$dates = explode("-", $fdate);
    	//print_r($dates);
    	$f_date = $dates['2'];
    	$new_date = date('d');
    	$new_month = date('m');
    	$new_year = date('Y');
    	for($i =0; $i<$frequency; $i++){

    		if($f_date >31){
    			$f_date =  $f_date;
    			$new_month = $new_month+1;
    			if($new_month > 12){
    				$new_month =1;
    				$new_year = $new_year+1;
    			}
    		}
    		$date[$i]['from'] =$new_year."-".$new_month."-".$f_date;
    		$f_date = $f_date+$days;
    		if($f_date >31){
    			$f_date =  $f_date;
    			$new_month = $new_month+1;
    			if($new_month > 12){
    				$new_month =1;
    				$new_year = $new_year+1;
    			}
    		}
    		$date[$i]['to'] =$new_year."-".$new_month."-".$f_date;
    		if((strtotime($date[$i]['from']) < strtotime(date("Y-m-d")) )&&( strtotime(date("Y-m-d")) < strtotime($date[$i]['to']))){
    			$return = $date[$i];
    		}
    		//echo $f_date;

    	}
    	//print_r($date);
    	//echo "F date:".$fdate."###".$frequency; exit;
    	return $return;
    }
