    		$approval_count_data [$count->transaction_type] [$count->current_status] = $count->count1;
    	}
    	$return['count'] = $approval_count_data;	
    	$query4=$callConfig->selectQuery(TBL_USERS,'id,display_name,user_photo','','','','');
		//echo $query3; exit;
