    	foreach ($user_data as  $user) {
    		$users[$user->id]['name'] = $user->display_name;
    		$users[$user->id]['photo'] = $user->user_photo;
    	}
    	$return['user'] = $users;
		//echo "<pre>"; print_r($approval_count_data); exit;
    	return $return;
    }
