	function movefileonedirtoanotherdir($source, $destination,$file,$other=''){
		$path = $destination;
		//echo $source."######".$destination."######".$file; exit;
		if(!is_dir($path)) { 		
			$dual_path = trim($path,'/');
			$dual_path = explode('/', $dual_path);
			$epath ="";
			foreach ($dual_path as $dpath) {
				$epath = $epath.$dpath."/";
				if(!is_dir($epath)){
					mkdir($epath); 
				}
			}
		}
		$returns = copy($source."/".$file, $destination."/".$file);
		return $returns;
	}
