function payrollupdateonetime($post,$get){
	global $callConfig;
    	//echo "<pre>";
	$erquery = $callConfig->selectQuery($post['type'],'*',"is_active=0",'','','');
	$erdata = $callConfig->getAllRows($erquery);
	foreach ($erdata as $er) {
		$earns[$er->name] = (array)$er;
