	}
	$row_data = $post['data']['0'];
		//print_r($row_data);
	unset($post['data']['0']);
	foreach ($post['data'] as $data) {
		$emp_code = $data['employ_code']['0'];
		$equery = $callConfig->selectQuery('employees','id',"emp_code='".$emp_code."'",'','','');
