	function gettasksdetails($get) {
		global $callConfig;
		$company_id = $get['company_id'];
		$filter_id = $get['filter_id'];
		$filter_table = $get['filter_table'];

		/* return buddy_list : from : general_code_details */
		$display_data = "SELECT id, genc_detail_code, genc_detail_name FROM general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='EMPLOYEEBUDDIES' order by id ASC"; 
		$display_details = $callConfig->getAllRows($display_data);
		$task_details['buddy_list'] = $display_details;	


		/* return filter_list : from : general_code_details */
		$display_data = "SELECT id, genc_detail_code, genc_detail_name FROM general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='FILTEROPTIONS'"; 
		$display_details = $callConfig->getAllRows($display_data);
		$task_details['filter_list'] = $display_details;	
		/*END return filter_list : from : general_code_details */


	$display_data = "select id, filter_name, apply_table_name, application_tablename, fieldname FROM application_filters WHERE company_id='".$company_id."' AND apply_table_name ='".$get['apply_table_name']."'  AND application_tablename='".$filter_table."' AND is_active='0'" ;  // change condition Rohan AND apply_table_name ='onboarding'
//echo $display_data; exit;
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['filter_option'] = $display_details;	


	/* return due_list : from : general_code_details */
	$display_data = "select id, genc_detail_code, genc_detail_name FROM general_code_details WHERE is_active='0' and company_id='".$company_id."' and genc_code='DUEDATETYPES'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['due_list'] = $display_details;	


	/* return period_list : from : general_code_details */
	$display_data = "select id, genc_detail_code, genc_detail_name FROM general_code_details WHERE is_active='0' and company_id='".$company_id."' and genc_code='DUEDATEPERIODS'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['period_list'] = $display_details;	


	/* return emp_list : from : employees */
	$display_data = "SELECT id, display_name, image, email_id FROM employees WHERE is_active='0' and company_id='".$company_id."'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['emp_list'] = $display_details;	

	$application_pagessql = "SELECT ap.insert_page_name,ap.application_table_name, da.page_title  FROM application_pages ap, display_attributes da WHERE ap.company_id = da.company_id AND ap.company_id = '".$company_id."' AND ap.application_table_name = da.application_table_name AND ap.is_active = da.is_active AND ap.is_active = 0"; 
	$application_pagesres = $callConfig->getAllRows($application_pagessql);
	$task_details['application_pages'] = $application_pagesres;	


	/* return due_list : from : general_code_details */
	$display_data = "select * FROM tasks_categories WHERE is_active='0' and company_id='".$company_id."'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['task_list'] = $display_details;	


	if($filter_id != ""){
		//$filterurl = "select * from filter_tables where is_active='0' and company_id='".$company_id."' AND transaction_id='".$filter_id."'"; 
		$filterurl = "select * FROM filter_tables WHERE is_active='0' and company_id='".$company_id."' AND id='".$filter_id."'"; 
		$filterdetails = $callConfig->getRow($filterurl);
		$task_details['filter_data'] = $filterdetails;
	}


	$process_task_settingssql = "SELECT * FROM process_task_settings WHERE company_id='".$company_id."' AND  id = '".$get['rid']."' AND is_active='0'"; 
	$process_task_settingsres = $callConfig->getRow($process_task_settingssql);
	$task_details['process_task_settings'] = $process_task_settingsres;
	
	$task_process_typesql = "SELECT id, genc_detail_code, genc_detail_name FROM general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='TASKPROCESSTYPE' order by id ASC"; 
	$task_process_typeres = $callConfig->getAllRows($task_process_typesql);
	$task_details['task_process_type'] = $task_process_typeres;	

	$triggerdatetypesql = "SELECT id, genc_detail_code, genc_detail_name FROM general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='TRIGGERDATETYPE'"; 
	$triggerdatetyperes = $callConfig->getAllRows($triggerdatetypesql);
	$task_details['trigger_date_type'] = $triggerdatetyperes;

	$email_contentsql = "SELECT id, template_name FROM email_content where is_active='0' and company_id='".$company_id."'"; 
	$email_contentres = $callConfig->getAllRows($email_contentsql);
	$task_details['email_content'] = $email_contentres;
	

