		$postdata_emerge['contact_mobile_no'] = $post['contact_mobile_no'][$emergeky];
		$postdata_emerge['contact_office_no'] = $post['contact_office_no'][$emergeky];
		$postdata_emerge['current_status'] = '0';
		if(!empty($post['contact_rowid'][$emergeky]))
		{
    // update

			$postdata_emerge['is_active'] = $post['is_active'];
			
			$postdata_emerge['updated_date'] = $post['updated_date'];
