			$postdata_edu['created_date'] = $post['updated_date'];
			$postdata_edu['created_by'] = $post['user_id'];
			$res=$callConfig->insertRecord(TBL_EMP_EDUCATIONS,$postdata_edu);
		}
		$retrunarry['TBL_EMP_EDUCATIONSarray'][] = $postdata_edu;
		$retrunarry['TBL_EMP_EDUCATIONS'][] = $res;

	}
	$retrunarry['postdata'] = $post;
	$whr = "table_id='".$post['emp_id']."'";
	$this->deleterows(TBL_APPLICATION_TEMP,$whr);
	
	$notdataa = array('company_id'=>$post['company_id'], 'notification_message'=>'Employee Details Successfully Updated', 'transaction_number'=>$post['emp_id'], 'application_table_name'=>'employees', 'type'=>'INFORMATION', 'notification_users'=>array($emp_user_id),'option'=>'COM_INSERT_ONBOARDING_EMPLOYEES');
	$ss = $this->tosendnotifiations($notdataa);
	$retrunarry['notification'] = $ss;
	return $retrunarry;
}


function employeesdisplayfieldsset($post,$get) {
	global $callConfig;
	$rowid = $post['rowid'];
	//print_r($post);
	if($rowid!='') {
		//update
		$storedata['company_id'] = $post['company_id'];
		$storedata['is_active'] = $post['is_active'];

		$storedata['updated_by'] = $post['user_id'];
		$storedata['updated_date'] = $post['updated_date'];
		$storedata['role_id'] = $post['role_type'];
		$storedata['field_list'] = $post['field_list'];
		$res=$callConfig->updateRecord(TBL_EMPLOYEES_DISPLAY_FIELDS,$storedata,'id',$rowid);
	} else {
		//insert
		$storedata['role_id'] = $post['role_type'];
		$storedata['company_id'] = $post['company_id'];
		$storedata['is_active'] = $post['is_active'];

		$storedata['field_list'] = $post['field_list'];
		$storedata['created_date'] = $storedata['updated_date'];
		$storedata['created_by'] = $post['user_id'];
		$res=$callConfig->insertRecord(TBL_EMPLOYEES_DISPLAY_FIELDS,$storedata);

	}
	

	return $res;
}


