                    $ids[]=$mainres['LASTID'];
                //echo "<pre>"; print_r($insert_array); print_r($mainres); exit;
                //$insert_arrays[] = $insert_array;

                }
            //echo "<pre>"; print_r($insert_arrays); exit;
            }

        }
        //print_r($ids);print_r($ids); exit;
        return $ids;
    }

function convertToYYYYMMDD($dateString) {
    $dateTime = date_create_from_format('Y-m-d', $dateString);
    if (!$dateTime) {
        $dateTime = date_create_from_format('d/M/y', $dateString);
    }
    if (!$dateTime) {
        $dateTime = date_create_from_format('d-M-y', $dateString);
    }
    if (!$dateTime) {
        $dateTime = date_create_from_format('d/m/y', $dateString);
    }
    if (!$dateTime) {
        $dateTime = date_create_from_format('d-m-y', $dateString);
    }
    if (!$dateTime) {
        $dateTime = date_create_from_format('m/d/Y', $dateString);
    }
    if (!$dateTime) {
        $dateTime = date_create_from_format('m-d-Y', $dateString);
    }
    if (!$dateTime) {
        $dateTime = date_create($dateString);
    }
    if ($dateTime) {
        return $dateTime->format('Y-m-d');
    } else {
        return false; // Invalid date format
    }
}

