    function togetidorinsertrow($data,$value,$get){
    	global $callConfig;
    	$return_id =0;
    	$return_array = array();
		//echo "Ravi<pre>"; print_r($data); echo $value; exit;
    	foreach ($data['data'] as  $key=>$val) {
    		if(strtolower($val) == strtolower($value)){
    			$return_id = $key;
    			break;
    		}
    	}
    	if($return_id ==0){
    		if($data['fileds']['table_name']!='general_code_details'){
    			$whre = "company_id=".$get['company_id']." AND ".$data['fileds']['display_field']." ='".$value."' AND is_active=0";
    			$pequery = $callConfig->selectQuery($data['fileds']['table_name'],'*',$whre,'','','');
    			$pedata = $callConfig->getRow($pequery);
    			$return_id = $pedata->id;
    			if($pedata->id!=""){
    				$return_id = $pedata->id;
    			}else{
    				$inserts_array = array('is_active'=>'0','current_status'=>0,'created_by'=>$get['user_id'],'created_date'=>date("Y-m-d H:i:s"),'company_id'=>$get['company_id']);
    				$inserts_array[$data['fileds']['display_field']] = $value;
    				$inres=$callConfig->insertRecord($data['fileds']['table_name'],$inserts_array);
    				$return_id = $inres['LASTID'];
    				$return_array = array('return_id'=>$inres['LASTID'],'value'=>$value);
    			}
    		}
    	}
    	$return['return_id'] = $return_id;
    	$return['return_array'] = $return_array;
		//print_r($return); exit;
		//echo $return_id; exit;
    	return $return;
    }
    function getemployeeattendance($post,$get){
    	global $callConfig;
    	$emp_list = $post['emplist'];
    	$month = $post['month'];
    	$year = $post['year'];
    	if(empty($emp_list)){
    		$query="SELECT id,display_name  FROM `employees` WHERE company_id = '".$get['company_id']."' and is_active =0";
    		$empdatas = $callConfig->getAllRows($query);
    		foreach ($empdatas as $value) {
    			$empidlist[$value->id] = $value->display_name;
    		}
    	}else{
    		foreach ($emp_list as $key=>$value) {
    			$empidlist[$key]=$value;
    		}
    	}
    	$attstc = "SELECT * FROM attendance_settings WHERE is_active=0 and company_id=".$get['company_id'];
    	$atsdata = $callConfig->getRow($attstc);

    	$shiftkeys = "SELECT * FROM attendance_key_types WHERE is_active=0 and company_id=".$get['company_id'];
    	$shiftkeysdata = $callConfig->getAllRows($shiftkeys);
    	foreach ($shiftkeysdata as $skey=>$svalue) {
    		$shift[$svalue->key_short_code] = (array)$svalue;
    	}
    	$holidays = "SELECT holiday_date FROM holidays WHERE is_active=0 and company_id=".$get['company_id']." AND holiday_year=".$year;
    	$holidaysdata = $callConfig->getAllRows($holidays);
    	foreach ($holidaysdata as $hkey=>$hvalue) {
    		$holidaysdatas[] = $hvalue->holiday_date;
    	}

    	$gencshiftkey = "SELECT * FROM general_code_details WHERE is_active=0 and company_id=".$get['company_id']." and genc_code='ATTENDANCE_KEY_TYPES'"; 
    	$gencshiftkeydata = $callConfig->getAllRows($gencshiftkey);
    	foreach ($gencshiftkeydata as $gkey => $gvalue) {
    		if($gvalue->genc_detail_code=='H'){
    			$genc_holiday_shiftkey= $gvalue->genc_detail_code;
    		}
    		else if($gvalue->genc_detail_code=='O'){
    			$genc_off_shiftkey= $gvalue->genc_detail_code;
    		}
    		else if($gvalue->genc_detail_code=='W'){
    			$genc_work_shiftkey= $gvalue->genc_detail_code;
    		}
    		else if($gvalue->genc_detail_code=='S'){
    			$genc_sick_shiftkey= $gvalue->genc_detail_code;
    		}
    		else if($gvalue->genc_detail_code=='R'){
    			$genc_partial_shiftkey= $gvalue->genc_detail_code;
    		}
    		else if($gvalue->genc_detail_code=='V'){
    			$genc_vacation_shiftkey= $gvalue->genc_detail_code;
    		}
    		else if($gvalue->genc_detail_code=='A'){
    			$genc_absence_shiftkey= $gvalue->genc_detail_code;
    		}
    	}

    	$min_working_hours = explode(":", $atsdata->minimum_hours_required);
    	$min_working_sec = (number_format($min_working_hours['0'])*3600)+(number_format($min_working_hours['1'])*60)+number_format($min_working_hours['2']); 
    	$office_starttime = $atsdata->office_start_time;
    	$grace_perieod = $atsdata->grace_perieod;
    	$office_starttime = strtotime($office_starttime)+strtotime($grace_perieod);
    	$office_starttime_hrs = explode(":", $office_starttime);
    	$office_starttime_sec = (((number_format($office_starttime_hrs['0'])*3600)+number_format($office_starttime_hrs['1']))*60)+number_format($office_starttime_hrs['2']); 
    	$half_working_hours = explode(":", $atsdata->half_day_hours);
    	$half_working_sec = (number_format($half_working_hours['0'])*3600)+(number_format($half_working_hours['1'])*60)+number_format($half_working_hours['2']); 
    	$workingdays = $atsdata->working_days;
    	$working_days = json_decode($workingdays,1);
    	$today_day= date('j');
    	$from=mktime(0, 0, 0, $month, '01', $year);
    	$from_date =  date("Y-m-d", $from);
    	$current_month= date('m');
    	$to=mktime(0, 0, 0, $month, $today_day, $year);
    	$to_date = $month>=$current_month ? date("Y-m-d", $to) : date('Y-m-t', strtotime($from_date));
    	foreach ($empidlist as $key => $empvalue) {
    		$attendancequery = "SELECT * from  employee_daily_attendances where is_active=0 AND employee_id = ".$key." AND  `attendace_date` >= '".$from_date."' AND `attendace_date` < '".$to_date."'";
    		unset($days);
    		unset($emp_reg);
    		$regularizequery = "select * from attendenace_regularization_requests where employee_id = ".$key." and current_status!=".ST_APPROVED;
    		$regularize = $callConfig->getAllRows($regularizequery);
    		foreach ($regularize as $regularization) {
    			$emp_reg[] = $regularization->regularization_date;
    		}
    		$attendance = $callConfig->getAllRows($attendancequery);
    		foreach ($attendance as $emptime) {
    			$days[$emptime->attendace_date] =  strtotime($emptime->attendace_date." ".$emptime->clock_out) - strtotime($emptime->attendace_date." ".$emptime->clock_in);
    			$clockin_hrs = explode(":", $emptime->clock_in); 
    			$clockin_sec = (((number_format($clockin_hrs['0'])*3600)+number_format($clockin_hrs['1']))*60)+number_format($clockin_hrs['2']); 
    			$clockin[$emptime->attendace_date]= $clockin_sec;
    		}
    		$datediff = strtotime($to_date) - strtotime($from_date);
    		$datediff = floor($datediff/(60*60*24));
    		for($i = 0; $i <= $datediff ; $i++){
    			$valda =  date("Y-m-d", strtotime($from_date . ' + ' . $i . 'day'));
    			$valday = strtolower(date("D", strtotime($from_date . ' + ' . $i . 'day')));
    			if(in_array($valda, (array)$holidaysdatas)){
        			//Holidays
    				$empattendance['S1displayvalue'] = $shift[$genc_holiday_shiftkey]['key_short_code'];
    				$empattendance['S1displaybgcolor'] = $shift[$genc_holiday_shiftkey]['key_bgcolor'];
    				$empattendance['S1displaytextcolor'] = $shift[$genc_holiday_shiftkey]['key_text_color'];
    				$empattendance['S2displayvalue'] = $shift[$genc_holiday_shiftkey]['key_short_code'];
    				$empattendance['S2displaybgcolor'] = $shift[$genc_holiday_shiftkey]['key_bgcolor'];
    				$empattendance['S2displaytextcolor'] = $shift[$genc_holiday_shiftkey]['key_text_color'];
    				$empattendance['first_reg'] = '0';
    				$empattendance['second_reg'] = '0';
    			}
    			else if(in_array($valday, (array)$working_days)){
        		//Working Days
    				if($min_working_sec > $days[$valda]){
    					if ($half_working_sec < $days[$valda]) {
    						$val['day'] = $valda;
    						if($office_starttime > $clockin[$valda]) {
    							//First Half Day Absent
    							$empattendance['S1displayvalue'] = $shift[$genc_partial_shiftkey]['key_short_code'];
    							$empattendance['S1displaybgcolor'] = $shift[$genc_partial_shiftkey]['key_bgcolor'];
    							$empattendance['S1displaytextcolor'] = $shift[$genc_partial_shiftkey]['key_text_color'];
    							$empattendance['S2displayvalue'] = $shift[$genc_work_shiftkey]['key_short_code'];
    							$empattendance['S2displaybgcolor'] = $shift[$genc_work_shiftkey]['key_bgcolor'];
    							$empattendance['S2displaytextcolor'] = $shift[$genc_work_shiftkey]['key_text_color'];
    							$empattendance['first_reg'] = '0';
    							$empattendance['second_reg'] = '0';
    							if(in_array($valda, (array)$emp_reg)){
    								$empattendance['first_reg'] = '1';
    							}
    						}else{
    							//Second Half Day Absent
    							$empattendance['S1displayvalue'] = $shift[$genc_work_shiftkey]['key_short_code'];
    							$empattendance['S1displaybgcolor'] = $shift[$genc_work_shiftkey]['key_bgcolor'];
    							$empattendance['S1displaytextcolor'] = $shift[$genc_work_shiftkey]['key_text_color'];
    							$empattendance['S2displayvalue'] = $shift[$genc_partial_shiftkey]['key_short_code'];
    							$empattendance['S2displaybgcolor'] = $shift[$genc_partial_shiftkey]['key_bgcolor'];
    							$empattendance['S2displaytextcolor'] = $shift[$genc_partial_shiftkey]['key_text_color'];
    							$empattendance['first_reg'] = '0';
    							$empattendance['second_reg'] = '0';
    							if(in_array($valda, (array)$emp_reg)){
    								$empattendance['second_reg'] = '1';
    							}
    						}
    					}else{
    						//Full Day absent
    						$val['day'] = $valda;
    						$empattendance['S1displayvalue'] = $shift[$genc_absence_shiftkey]['key_short_code'];
    						$empattendance['S1displaybgcolor'] = $shift[$genc_absence_shiftkey]['key_bgcolor'];
    						$empattendance['S1displaytextcolor'] = $shift[$genc_absence_shiftkey]['key_text_color'];
    						$empattendance['S2displayvalue'] = $shift[$genc_absence_shiftkey]['key_short_code'];
    						$empattendance['S2displaybgcolor'] = $shift[$genc_absence_shiftkey]['key_bgcolor'];
    						$empattendance['S2displaytextcolor'] = $shift[$genc_absence_shiftkey]['key_text_color'];
    						$empattendance['first_reg'] = '0';
    						$empattendance['second_reg'] = '0';
    						if(in_array($valda, (array)$emp_reg)){
    							$empattendance['first_reg'] = '1';
    							$empattendance['second_reg'] = '1';
    						}	
    					}
    				}else{
    					//Full day Present
    					$empattendance['S1displayvalue'] = $shift[$genc_work_shiftkey]['key_short_code'];
    					$empattendance['S1displaybgcolor'] = $shift[$genc_work_shiftkey]['key_bgcolor'];
    					$empattendance['S1displaytextcolor'] = $shift[$genc_work_shiftkey]['key_text_color'];
    					$empattendance['S2displayvalue'] = $shift[$genc_work_shiftkey]['key_short_code'];
    					$empattendance['S2displaybgcolor'] = $shift[$genc_work_shiftkey]['key_bgcolor'];
    					$empattendance['S2displaytextcolor'] = $shift[$genc_work_shiftkey]['key_text_color'];
    					$empattendance['first_reg'] = '0';
    					$empattendance['second_reg'] = '0';
    				}
    			}else{
					// Weekoff
    				$empattendance['first_reg'] = '0';
    				$empattendance['second_reg'] = '0';
    				$empattendance['S1displayvalue'] = $shift[$genc_off_shiftkey]['key_short_code'];
    				$empattendance['S1displaybgcolor'] = $shift[$genc_off_shiftkey]['key_bgcolor'];
    				$empattendance['S1displaytextcolor'] = $shift[$genc_off_shiftkey]['key_text_color'];
    				$empattendance['S2displayvalue'] = $shift[$genc_off_shiftkey]['key_short_code'];
    				$empattendance['S2displaybgcolor'] = $shift[$genc_off_shiftkey]['key_bgcolor'];
    				$empattendance['S2displaytextcolor'] = $shift[$genc_off_shiftkey]['key_text_color'];
    			}
    			$empattendance_data[$i]=$empattendance; 
    		}
    		$empattendance_details[$key]=$empattendance_data; 
    	}
    	$empattendancedata['emp_names'] = $empidlist;
    	$empattendancedata['emp_attendance'] = $empattendance_details;
		//echo "<pre>"; print_r($empattendance_details);exit;
    	return $empattendancedata;
    }
    function togetallpayslipdetails($post){
    	global $callConfig;
    	$whr1st="company_id= '".$post['company_id']."' and is_active='0'";
    	$query1st = $callConfig->selectQuery('employees','*',$whr1st,'','','');
    	$emp_details = $callConfig->getAllRows($query1st);
    	foreach ($emp_details as $emp) {
    		$empdatas[$emp->id]=array('display_name'=>$emp->display_name,'emp_code'=>$emp->emp_code);
    	}
    	$whr1st="company_id= '".$post['company_id']."' and pay_month='".$post['month']."' and pay_year='".$post['year']."' AND is_active=0";
    	$query1st = $callConfig->selectQuery('pay_run_summary','*',$whr1st,'','','');
    	$st1 = $callConfig->getAllRows($query1st);
    	$st1 = (array)$st1;
    	foreach ($st1 as $key=>$value) {
    		$value= (array)$value;		
    		$actual_amount =0;
    		$dedaction_amount =0;
    		$whr1stm = "pay_run_summary_id=".$value['id']." AND is_active = 0" ;
    		$query1stm = $callConfig->selectQuery('pay_run_summary_components','*',$whr1stm,'','','');
    		$stmp = $callConfig->getAllRows($query1stm);
    		foreach ($stmp as $stmpkey=>$stmpvalue) {
    			if($stmpvalue->compnent_type !=1){
    				$actual_amount = $actual_amount+$stmpvalue->salary_component_actual;
    			}else{
    				$dedaction_amount = $dedaction_amount+$stmpvalue->salary_component_actual;
    			}
    		}
    		$data[$key] = $value;
    		$data[$key]['earning_amount'] = number_format($actual_amount,2);
    		$data[$key]['deduction_amount'] = number_format($dedaction_amount,2);
    		$data[$key]['net'] = number_format($actual_amount- $dedaction_amount,2);
    		$data[$key]['emp_name'] = $empdatas[$value['employee_id']]['display_name'];
    		$data[$key]['emp_code'] = $empdatas[$value['employee_id']]['emp_code'];
    	}
    	return $data;
    }

