    		$esi_setup = array('esi_no'=>$post['esi_no'],'deduction_cycle'=>$post['esi_deduction_cycle'],'employee_contribution'=>$post['esi_employee_contribution'],'employer_contribution'=>$post['esi_employer_contribution'],'employer_contribution_in_ctc'=>$post['esi_employer_contribution_in_ctc']);
