    		$pt_setup_full = array_merge($pt_setup,$common_field);
    		$res=$callConfig->insertRecord(TBL_PROFESSIONAL_TAX,$pt_setup_full);
    	}
    	if($post['pf_checked']){
    		$pf_setup = array('epf_number'=>$post['epf_number'],'deduction_cycle'=>$post['epf_deduction_cycle'],'employee_contribution'=>$post['epf_employee_contribution'],'employer_contribution'=>$post['epf_employer_contribution'],'employer_contribution_in_ctc'=>$post['epf_employer_contribution_in_ctc']);
    		$pf_setup_full = array_merge($pf_setup,$common_field);
    		$res=$callConfig->insertRecord(TBL_PROVIDENT_FUNDS,$pf_setup_full);
    	}
    	if($post['lwf_checked']){
    		$lwf_setup = array('created_by'=>$post['created_by'],'state_id'=>$post['lwf_state_id'],'deduction_cycle'=>$post['lwf_deduction_cycle'],'employee_contribution'=>$post['lwf_employee_contribution'],'employer_contribution'=>$post['lwf_employer_contribution']);
    		$lwf_setup_full = array_merge($lwf_setup,$common_field);
    		$res=$callConfig->insertRecord(TBL_LABOUR_WELFARE_FUNDS,$lwf_setup_full);
    	}
    	$updatequery = "update ".TBL_EARNINGS." set is_active='1' where id not in (".$post['selectedcomponents'].")";
    	$callConfig->executeQuery($updatequery);

    	$updatequeryoe = "update ".TBL_OTHER_EARNINGS." set is_active='1' where id not in (".$post['selected_other_earnings'].")";
    	return $res;
    }


