    function togetleaveform($get){
    	global $callConfig;
    	$whr="is_active='0' and company_id=".$get['company_id'];
    	$query=$callConfig->selectQuery('leave_categories','*',$whr,'','','');
    	$categories = $callConfig->getAllRows($query);
    	$details['leave_categories'] = (array)$categories;

    	$whrcon = "is_active='0' and company_id=".$get['company_id']." and id=".$get['id'];
    	$query=$callConfig->selectQuery('leave_types','*',$whrcon,'','','');
    	$leavetypes = $callConfig->getRow($query);
    	$details['leave_types'] = $leavetypes;

    	$whrcon = "is_active='0' and company_id=".$get['company_id']." and leave_type_id=".$get['id'];
    	$query=$callConfig->selectQuery('leave_type_levels','*',$whrcon,'','','');
    	$leavetypes = $callConfig->getAllRows($query);
    	$details['leave_type_levels'] = $leavetypes;

