   function setupvendor($post,$get){
	global $callConfig;
	unset($post['document_id']);
	$returnddd['post'] = $post;
	$user_idd = $post['user_idd'];
	unset($post['user_idd']);
	if($get['rid']==''){
		$post['current_status'] = "0";
		$res=$callConfig->insertRecord(TBL_VENDOR_REGISTERS,$post);
		$returnddd['upinsertvr'] = $res;
		$transaction_number = $res['LASTID'];
		$attachlist = json_decode($post['attachments'],1);
		foreach ($attachlist as $dvalue) {
			$filename = $dvalue['filename'];
			$doctype = $dvalue['document_id'];
			if($filename!="" && $dvalue['categoryid'] !=""){
				$fields = array('company_id'=>$get['company_id'],'vendor_user_id'=>$user_idd,'document_id'=>$dvalue['categoryid'],'filename'=>$filename,'category_id'=>$doctype,'created_by'=>$get['user_id'],'is_active'=>'0','current_status'=>ST_APPROVAL_PENDING,'created_date'=>date("Y-m-d H:i:s"));
				$res1=$callConfig->insertRecord('vendor_documents',$fields);
				$returnddd['insert'] = $res1;
			}
		}
	}else{
		$res=$callConfig->updateRecord(TBL_VENDOR_REGISTERS,$post,'id',$get['rid']);
		$returnddd['insertvr'] = $res;
		$attachlist = json_decode($post['attachments'],1);
	
	foreach ($attachlist as $dvalue) {
			$filename = $dvalue['filename'];
			$doctype = $dvalue['document_id'];
		if($filename!="" && $dvalue['categoryid'] !=""){	
			if($dvalue['doc_id']!=""){ 
				$fields = array('company_id'=>$get['company_id'],'vendor_user_id'=>$user_idd,'document_id'=>$dvalue['categoryid'],'filename'=>$filename,'category_id'=>$doctype);
				$insert_data=$callConfig->updateRecord('vendor_documents',$fields,'id',$dvalue['doc_id']);
		 		$returnddd['update'][] = $insert_data;
			}else{
				$fields = array('company_id'=>$get['company_id'],'vendor_user_id'=>$user_idd,'document_id'=>$dvalue['categoryid'],'filename'=>$filename,'category_id'=>$doctype,'created_by'=>$get['user_id'],'is_active'=>'0','current_status'=>ST_APPROVAL_PENDING,'created_date'=>date("Y-m-d H:i:s"));
				$res1=$callConfig->insertRecord('vendor_documents',$fields);
				$returnddd['insert'][] = $res1;					
			}
		}	
		}
	}
	return $returnddd;
}
    function getvendorsettings($get){
    	global $callConfig;

    	$vendor_registerssql = "SELECT * FROM `vendor_registers` WHERE company_id = '".$get['company_id']."' AND user_id = '".$get['user_id']."' AND is_active=0";
    	$vendor_registersres = $callConfig->getRow($vendor_registerssql);
    	$details['vendor_registers'] = $vendor_registersres;

    	$application_user_invitationssql = "SELECT connect_users, company_name FROM `application_user_invitations` WHERE company_id = '".$get['company_id']."' AND user_id = '".$get['user_id']."' AND is_active=0";
    	$application_user_invitationsres = $callConfig->getRow($application_user_invitationssql);
    	$details['application_user_invitations'] = $application_user_invitationsres;

    	$display_data = "select genc_detail_code,genc_detail_name from general_code_details where is_active='0' and company_id='".$get['company_id']."'  and genc_code='BANKACCTTYPE'"; 
		$display_details = $callConfig->getAllRows($display_data);
		$details['bankactype'] = $display_details;

		$vendor_documents = "SELECT * FROM vendor_documents WHERE company_id='".$get['company_id']."'  AND vendor_user_id = '".$get['user_id']."' AND is_active='0'"; 
		$display_details = $callConfig->getAllRows($vendor_documents);
		$details['vendor_documents'] = $display_details;


    	$whrcat ="company_id = '".$get['company_id']."' AND is_active=0";
    	$query=$callConfig->selectQuery('countries','id,country_name',$whrcat,'','','');
    	$components6= (array)$callConfig->getAllRows($query);
    	$details['countries'] = (array)$components6;

    	$statessql = "SELECT id, state_name FROM `states` WHERE company_id = '".$get['company_id']."' AND (country_id = '".$vendor_registersres->billing_country."' || country_id = '".$vendor_registersres->shipping_country."') AND is_active=0";
    	$statesres = $callConfig->getAllRows($statessql);
    	$details['states'] = $statesres;

    	$citiessql = "SELECT id, city_name FROM `cities` WHERE company_id = '".$get['company_id']."' AND (state_id = '".$vendor_registersres->billing_state."' || state_id = '".$vendor_registersres->shipping_state."') AND is_active=0";
    	$citiesres = $callConfig->getAllRows($citiessql);
    	$details['cities'] = $citiesres;






    	$query="SELECT id,document_name,document_list_types  FROM `document_lists` WHERE company_id = '".$get['company_id']."' and is_active =0 and category_id in (select id from document_categories where id='".ST_VENDOR_REGISTRATION."' and is_active ='0')";
    	$components6 = $callConfig->getAllRows($query);
    	foreach ($components6 as $cmp) {
    		$document_lists[$cmp->id]=$cmp;
    	}
    	$details['document_lists'] = $document_lists;
    	$query1="SELECT id,document_list_id,document_type  FROM `document_list_types` WHERE company_id = '".$get['company_id']."' and is_active =0";
    	$components7 = $callConfig->getAllRows($query1);
    	foreach ($components7 as $cmplist) {
    		$document_list_types[$cmplist->document_list_id][]=$cmplist;
    	}
    	$details['document_list_types'] =$document_list_types;
    	return $details;
    } 
