    /* Announcements Feeds Page Start */
    function getannouncements($get){
    	global $callConfig;
    	$whrconfig ="is_active='0' and company_id=".$get['company_id'];  
    	$queryconfig=$callConfig->selectQuery('config','name,display_logo,location',$whrconfig,'','','');
