    		$querysumm = "SELECT sum(IF(comments!='', 1,0 ) ) as totalcomments,sum(IF(like_type=1, 1,0 ) ) as totallikes ,sum(IF(like_type=2, 1,0 ) ) as totaldislikes FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and userid=".$get['userid']." and announcement_id=".$announcesvalue->id ;
    		$announcessummaryuser = $callConfig->getRow($querysumm); 
    		$userannounces[$announcesvalue->id]['totallikes'] = $announcessummaryuser->totallikes == null ? '0' : $announcessummaryuser->totallikes;
    		$userannounces[$announcesvalue->id]['totaldislikes'] = $announcessummaryuser->totaldislikes == null ? '0' : $announcessummaryuser->totaldislikes;
    		$userannounces[$announcesvalue->id]['totalcomments'] = $announcessummaryuser->totalcomments == null ? '0' : $announcessummaryuser->totalcomments;
    	}
    	$details['userannounces'] = $userannounces;
