    	}
    	$queryannounces = "SELECT * FROM company_announcements WHERE is_active=0 and company_id=".$get['company_id'].$announcement_category_id."  and expiry_date>='".date("Y-m-d")."' order by start_date desc" ;
    	$announces = $callConfig->getAllRows($queryannounces);
    	foreach ($announces as $announceskey => $announcesvalue) {
    		$announceslist[$announcesvalue->id] = (array)$announcesvalue;
    		$announceslist[$announcesvalue->id]['announcement_category_name'] = $announce_category_id[$announcesvalue->announce_category_id];
    		$emp_id = $announcesvalue->created_by;
    		$queryemp = "SELECT display_name,image FROM employees WHERE is_active=0 and company_id=".$get['company_id']." and id=".$emp_id;
    		$empdata = $callConfig->getRow($queryemp);
    		$announceslist[$announcesvalue->id]['created_by_image'] = $empdata->image;
    		$announceslist[$announcesvalue->id]['display_name'] = $empdata->display_name;
    		$querysumm = "SELECT sum(IF(comments!='', 1,0 ) ) as totalcomments,sum(IF(like_type=1, 1,0 ) ) as totallikes ,sum(IF(like_type=2, 1,0 ) ) as totaldislikes FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_id=".$announcesvalue->id;
    		$announcessummary = $callConfig->getRow($querysumm);    	
    		$announceslist[$announcesvalue->id]['totallikes'] = $announcessummary->totallikes == null ? '0' : $announcessummary->totallikes;
    		$announceslist[$announcesvalue->id]['totaldislikes'] = $announcessummary->totaldislikes == null ? '0' : $announcessummary->totaldislikes;
    		$announceslist[$announcesvalue->id]['totalcomments'] = $announcessummary->totalcomments == null ? '0' : $announcessummary->totalcomments;
    		$querysumm = "SELECT count(id) as liked FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_id=".$announcesvalue->id." and userid='".$get['userid']."' and msg_type='2' and like_type='1'";
    		$announcessummary = $callConfig->getRow($querysumm);
    		$announceslist[$announcesvalue->id]['highlight_like'] = $announcessummary->liked == 0 ? '0' : '1';
    		$querysumm = "SELECT count(id) as disliked FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_id=".$announcesvalue->id." and userid='".$get['userid']."' and msg_type='2' and like_type='2'";
    		$announcessummary = $callConfig->getRow($querysumm);
    		$announceslist[$announcesvalue->id]['highlight_dislike'] = $announcessummary->disliked == 0 ? '0' : '1';
    		$querysumm = "SELECT count(id) as commented FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_id=".$announcesvalue->id." and userid='".$get['userid']."' and msg_type='1' and like_type='0'";
    		$announcessummary = $callConfig->getRow($querysumm);
    		$announceslist[$announcesvalue->id]['highlight_comment'] = $announcessummary->commented == 0 ? '0' : '1';
    	}
    	$details['announcements'] = $announceslist;	
    	$queryannounceshistory = "SELECT * FROM company_announcements WHERE is_active=0 and company_id=".$get['company_id']." and MONTH(expiry_date)=MONTH('".date("Y-m-d")."') order by start_date desc" ;
    	$announceshistory = $callConfig->getAllRows($queryannounceshistory);
    	foreach ($announceshistory as $announceskey => $announcesvalue) {
    		$historyannouncesmonth[$announcesvalue->id] = (array)$announcesvalue;
    		$querysumm = "SELECT sum(IF(comments!='', 1,0 ) ) as totalcomments,sum(IF(like_type=1, 1,0 ) ) as totallikes ,sum(IF(like_type=2, 1,0 ) ) as totaldislikes FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_id=".$announcesvalue->id;
    		$announcessummary = $callConfig->getRow($querysumm);    	
    		$historyannouncesmonth[$announcesvalue->id]['totallikes'] = $announcessummary->totallikes == null ? '0' : $announcessummary->totallikes;
    		$historyannouncesmonth[$announcesvalue->id]['totaldislikes'] = $announcessummary->totaldislikes == null ? '0' : $announcessummary->totaldislikes;
    		$historyannouncesmonth[$announcesvalue->id]['totalcomments'] = $announcessummary->totalcomments == null ? '0' : $announcessummary->totalcomments;
    	}
    	$details['current_month_announcements'] = $historyannouncesmonth;	
    	$queryannounceshistory = "SELECT * FROM company_announcements WHERE is_active=0 and company_id=".$get['company_id']." and YEAR(expiry_date)=YEAR('".date("Y-m-d")."') order by start_date desc" ;
    	$announceshistory = $callConfig->getAllRows($queryannounceshistory);
    	foreach ($announceshistory as $announceskey => $announcesvalue) {
    		$historyannouncesyear[$announcesvalue->id] = (array)$announcesvalue;
    		$querysumm = "SELECT sum(IF(comments!='', 1,0 ) ) as totalcomments,sum(IF(like_type=1, 1,0 ) ) as totallikes ,sum(IF(like_type=2, 1,0 ) ) as totaldislikes FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_id=".$announcesvalue->id;
    		$announcessummary = $callConfig->getRow($querysumm);    	
    		$historyannouncesyear[$announcesvalue->id]['totallikes'] = $announcessummary->totallikes == null ? '0' : $announcessummary->totallikes;
    		$historyannouncesyear[$announcesvalue->id]['totaldislikes'] = $announcessummary->totaldislikes == null ? '0' : $announcessummary->totaldislikes;
    		$historyannouncesyear[$announcesvalue->id]['totalcomments'] = $announcessummary->totalcomments == null ? '0' : $announcessummary->totalcomments;
    	}
    	$details['current_year_announcements'] = $historyannouncesyear;	

    	/*$admin_announce_data = "select annoucements_rights_roleid from config where company_id='".$get['company_id']."' and is_active='0'";
        $announc_rights = $callConfig->getRow($admin_announce_data);
        $admin_roleid = $announc_rights->annoucements_rights_roleid;
        $details['annoucements_rights_roleid'] = $admin_roleid;	*/

        return $details;
    }
