	function toGetTransactionLogdata($get){
		global $callConfig;
		if($get['status']!=""){
			$quer_5="SELECT *  FROM `transaction_approval_logs` WHERE company_id='".$get['company_id']."' and user_id =".$get['user_id']." and response_type = ".$get['status']." ORDER BY id DESC";
		}else{
			$quer_5="SELECT *  FROM `transaction_approval_logs` WHERE company_id='".$get['company_id']."' and user_id =".$get['user_id']."  ORDER BY id DESC";
    		//echo $quer_5;
		}
		$tra_data = $callConfig->getAllRows($quer_5);
    	//echo "<pre>";print_r($tra_data);
		$response = array();
		foreach ($tra_data as $tra) {
			$que="SELECT *  FROM ".$tra->transaction_table."  WHERE id='".$tra->transaction_id."'";
			$rowdat = $callConfig->getRow($que);
			$tra->data = $rowdat;
			$tra_all[$tra->id] = $tra;
			$tral[$tra->transaction_table][] = $tra;
			if($tra->response_type==0){
				$count[$tra->transaction_table][] = $tra->id;
				$all_count[] = $tra->id;
			}
			if(!in_array($tra->transaction_table, (array)$response)){	    		
				$response[] = $tra->transaction_table;
			}
		}
		$emp_que = "SELECT *  FROM `employees`";
		$emp_details = $callConfig->getAllRows($emp_que);
		foreach ($emp_details as $emp) {
			$emp_data[$emp->user_id] = $emp;
		}
		$return['cat_all']=$tral;
		$return['cat_all']['all']=$tra_all;
		$return['cat_type']=$response;    	
		$return['all_count']=$all_count;
		$return['cat_count']=$count;
		$return['emp']=$emp_data;
		return $return;
	}
