    		$queryresponse = "SELECT * FROM ".TBL_SURVEY_SETUP." WHERE is_active=0 and company_id=".$get['company_id']." and id=".$get['survey_id']." and category=".$get['category'] ; 
    		$response = $callConfig->getRow($queryresponse);
