            function addupdateproject($post, $get){
            	global $callConfig;
  		//echo "<pre>"; print_r($post); exit;
            	$fieldnames=array('company_id'=>$post['company_id'],'name'=>$post['name'],'description'=>$post['descrption'],'customer_id'=>$post['customer_id'],'billing_method_id'=>$post['billing_method_id'],'project_cost'=>$post['project_cost'],'budget_type'=>$post['budget_type'],'add_budget_project'=>$post['add_budget_project']=='on'?'1':'0','is_active'=>'0','current_status'=>0,'created_date'=>$post['created_date'],'created_by'=>$post['created_by']);
   		//echo "<pre>"; print_r($fieldnames); exit;
            	if($post['rid']!=""){
            		$project_id = $post['rid'];
            		$res=$callConfig->updateRecord('projects',$fieldnames,'id',$post['rid']);
            		$callConfig->executeQuery("update project_users set is_active=1 where project_id =".$project_id);
            		$callConfig->executeQuery("update project_tasks set is_active=1 where project_id =".$project_id);

            	}else{
            		$inres=$callConfig->insertRecord('projects',$fieldnames);
            		$project_id = $inres['LASTID'];
            	}

            	foreach($post['user'] as $key=>$user){
            		$inserts_array=array('company_id'=>$post['company_id'],'project_id'=>$project_id,'user_id'=>$user,'email'=>$post['user_email'][$key],'rate_hours'=>$post['user_rate_hour'][$key],'is_active'=>'0','current_status'=>0,'created_date'=>$post['created_date'],'created_by'=>$post['created_by']);
            		if($post['puser_id'][$key]!=""){
            			$res=$callConfig->updateRecord('project_users',$inserts_array,'id',$post['puser_id'][$key]);
            		}else{
            			$inres=$callConfig->insertRecord('project_users',$inserts_array);	
            		}

            	}
            	foreach($post['task_name'] as $key=>$task_name){
            		$inserts_task=array('company_id'=>$post['company_id'],'project_id'=>$project_id,'task_name'=>$task_name,'description'=>$post['task_description'][$key],'rate_hours'=>$post['task_rate_hour'][$key],'budget_hours'=>$post['task_budget_hour'][$key],'bill_type'=>$post['bill_type'][$key]=='on'?'1':'0','is_active'=>'0','current_status'=>0,'created_date'=>$post['created_date'],'created_by'=>$post['created_by']);
            		if($post['ptask_id'][$key]!=""){
            			$res=$callConfig->updateRecord('project_tasks',$inserts_task,'id',$post['ptask_id'][$key]);
            		}else{
            			$inres=$callConfig->insertRecord('project_tasks',$inserts_task);	
            		}

   				//echo "<pre>"; print_r($inserts_task); 
            	}
            	return $inres;
            }
