            function getcontractemployees($get){
            	global $callConfig;
        //echo "ravi"; exit;
            	$current_month = date('m');
            	$whr="company_id=".$get['company_id']." and is_active='0' and vendor_id=".$get['vendor_id'];
            	$query=$callConfig->selectQuery(TBL_EMPLOYEES,'id,display_name,image,email_id',$whr,'','','');
            	$emplist = $callConfig->getAllRows($query);
        //print_r( $emplist);
            	foreach($emplist as $empdata){
            		$whrc="company_id=".$get['company_id']." and is_active='0' AND current_status =".ST_APPROVED." and emp_id=".$empdata->id." and YEARWEEK(timesheet_date) = YEARWEEK(NOW())";
            		$queryp=$callConfig->selectQuery(TBL_PROJECT_TIMESHEETS,'sum(billable_hrs) as time_spent,count(id) as count',$whrc,'','','');
        //echo $queryp ; exit;
            		$project_users = $callConfig->getRow($queryp);
            		if(($project_users->count)>0){
            			$empdata->timesheet = "Approved";
            			$empdata->total_timespent = $project_users->time_spent;
            		}else{
            			$empdata->timesheet = "Submission Pending";
            			$empdata->total_timespent = "0";
            		}
            		$empdata->total_scheduletime = 40;
            		$empdetails[] = $empdata;
            	}
            	$details['emplist_week'] = $empdetails;
            	$whr="company_id=".$get['company_id']." and is_active='0' and vendor_id=".$get['vendor_id'];
            	$query=$callConfig->selectQuery(TBL_EMPLOYEES,'id,display_name,image,email_id',$whr,'','','');
            	$emplist = $callConfig->getAllRows($query);
            	foreach($emplist as $empdata){
            		$whrcon="company_id=".$get['company_id']." and is_active='0' AND current_status =".ST_APPROVED." and emp_id=".$empdata->id." and MONTH(timesheet_date) = MONTH(CURRENT_DATE()) AND YEAR(timesheet_date) = YEAR(CURRENT_DATE())";
            		$queryp1=$callConfig->selectQuery(TBL_PROJECT_TIMESHEETS,'sum(billable_hrs) as time_spent,count(id) as count',$whrcon,'','','');
            		$project_users1 = $callConfig->getRow($queryp1);
            		if($project_users1->count>0){
            			$empdata->timesheet = "Approved";
            			$empdata->total_timespent = $project_users1->time_spent;
            		}else{
            			$empdata->timesheet = "Submission Pending";
            			$empdata->total_timespent = "0";
            		}
            		$empdata->total_scheduletime =160;
            		$empdetail[]= $empdata;
            	}
            	$details['emplist_month'] = $empdetail;
        //echo "<pre>"; print_r($details); exit;
            	return $details;
            }
            function togetjobdetails($get){
            	global $callConfig;
            	$query = "SELECT * FROM job_categories WHERE is_active=0";
            	$data = $callConfig->getAllRows($query);
            	foreach ($data as $value) {	
            		$main[$value->id] = (array)$value;
            	}
            	$query3 = "SELECT * FROM `job_titles` WHERE is_active=0" ;
            	$data3 = $callConfig->getAllRows($query3);		
            	foreach ($data3 as  $value3) {
            		$vv=array('id'=>$value3->id,'name'=>$value3->job_title);
            		$main[$value3->job_category_id]['data'][]= $vv;
            	}
            	$year = $get['year']!="" ? $get['year'] : date('Y');
            	$no_array =array('01','02','03','04','05','06','07','08','09','10','11','12');
            	foreach ($no_array as $mont) {
            		$datt = $year."-".$mont;
            		$query = "SELECT * FROM manpower_requisitions WHERE is_active=0 AND transaction_month_date='".$datt."'";
            		$data3 = $callConfig->getAllRows($query);		
            		$da[$mont]= array();
            		$len = array();
            		foreach($data3 as $dd){
            			$len[$dd->job_title_id] = $dd;
            		}
            		$da[$mont] = $len;
            	} 
            	$vquery = "SELECT id,first_name FROM vendors WHERE is_active=0";
            	$vendors = $callConfig->getAllRows($vquery);
            	$vquery = "SELECT id,location_name FROM locations WHERE is_active=0";
            	$locations = $callConfig->getAllRows($vquery);
            	$vquery = "SELECT id,department_name FROM departments WHERE is_active=0";
            	$departments = $callConfig->getAllRows($vquery);
            	$vquery = "SELECT id,job_title FROM job_titles WHERE is_active=0";
            	$job_titles = $callConfig->getAllRows($vquery);

            	$return['main'] = $main;
            	$return['job_data'] = $da;
            	$return['vendors'] = $vendors;
            	$return['locations'] = $locations;
            	$return['departments'] = $departments;
            	$return['job_titles'] = $job_titles;
            	return $return;

            }
            function toinsertempcontracts($post, $get){
            	global $callConfig;
            	$tran_number = $this->toGetApplicationSerialNumber('vendor_contracts');
            	$inserts_task =  array('company_id'=>$get['company_id'], 'name'=>$post['name'], 'vendor_id'=>$post['vendor'], 'contract_year'=>$post['fiscal_year'], 'transaction_number'=>$tran_number, 'is_active'=>'0', 'current_status'=>'0', 'created_date'=>$post['now_date'], 'created_by'=>$post['user_id']);
            	$inres=$callConfig->insertRecord('vendor_contracts',$inserts_task);

            	for($i=1;$i<$post['count'];$i++){
            		for($k=1;$k<13;$k++){
            			$nojobs = "name_".$i."_".$k;
            			if($post[$nojobs]!=""){
            				if($post[$nojobs]!="0"){
            					$job = "name_".$i."_account_code";
            					$inserts_task =  array('company_id'=>$get['company_id'], 'vendor_contract_id'=>$inres['LASTID'], 'job_title_id'=>$post[$job], 'no_of_vacancy'=>$post[$nojobs], 'contract_year'=>$post['fiscal_year'],'contract_month'=>$k, 'is_active'=>'0', 'current_status'=>'0', 'created_date'=>$post['now_date'], 'created_by'=>$post['user_id']);
            					$inres=$callConfig->insertRecord('vendor_contract_details',$inserts_task);
						//$query = "select * or,"
            					print_r($inserts_task); echo"<br>";
            				}
            			}
            		}
            	}
            	echo "<pre>Ravi"; print_r($inserts_task); exit;
            }
