		$response = $callConfig->getAllRows($queryresponse);
		foreach($response as $emp){
			$employees[$emp->id] = $emp->display_name;
		}
		$details['employees'] = $employees;

		$queryresponse = "SELECT count(id) as total_assessments_responses FROM ".TBL_ASSESSMENT_RESPONSES." WHERE is_active=0 and company_id=".$get['company_id']." and assessment_id=".$get['assessment_id']." and current_status=".ST_COMPLETE;
		$response = $callConfig->getRow($queryresponse);
		$details['no_of_responds'] = $response->total_assessments_responses==''? '0': $response->total_assessments_responses;

		$queryresponse = "SELECT count(id) as total_responses FROM ".TBL_ASSESSMENT_RESPONSES." WHERE is_active=0 and company_id=".$get['company_id']." and assessment_id=".$get['assessment_id'];
		$response = $callConfig->getRow($queryresponse);
		$total_responses = $response->total_responses==''? '0': $response->total_responses;
		if($total_responses>0){
			$details['rate']= round($details['no_of_responds']/$total_responses *100 ,2);
		}else
		{
			$details['rate'] = "0 ";
		}

		$queryresponse = "SELECT * FROM ".TBL_ASSESSMENT_RESPONSES." WHERE is_active=0 and company_id=".$get['company_id']." and assessment_id=".$get['assessment_id']." group by employee_id"; 
		$response = $callConfig->getAllRows($queryresponse);
		$details['response'] = $response;
		return $details;
	}


