		$whr="company_id=".$get['company_id']." and is_active='0' and id=".$get['assessment_id'];
		$query=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP,'*',$whr,'','','');
		$details['assessment_details'] = $callConfig->getRow($query);

		$whr2="company_id=".$get['company_id']." and is_active='0' and genc_code='ASSESSMENT_QTYPE'";
		$query=$callConfig->selectQuery('general_code_details','genc_detail_code,genc_detail_name',$whr2,'','','');
		$details['qustion_types'] = $callConfig->getAllRows($query);

		$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$get['assessment_id'];
		$query=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTIONS,'*',$whr,'','','');
		$assessment_qustion_details = $callConfig->getAllRows($query);
		foreach ($assessment_qustion_details as $value) {
			$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$get['assessment_id']." and question_id=".$value->id;
			$query_ans=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTION_OPTIONS,'*',$whr,'','','');
			$assessment_answer_details = $callConfig->getRow($query_ans);
			$disp_question[$value->id]['assessment_question'] = $value->assessment_question;
			$disp_question[$value->id]['options_display_type'] = $value->options_display_type;
			$disp_question[$value->id]['assessment_correct_option'] = $assessment_answer_details->assessment_correct_option;
			$disp_question[$value->id]['allow_multiple_selections'] = $value->allow_multiple_selections;
			$disp_question[$value->id]['assessment_question_option'] = $assessment_answer_details->assessment_question_option;

		}
		$details['questions'] = $disp_question;
		return $details;
	}

	function getassessmentreport($get){
		global $callConfig;
		$Qtypes = array('MultilpleChoice'=>'MCQ','CheckboxQuestion'=>'MCA','FreeText'=>'FT');

		$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$get['assessment_id'];
		$query=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTIONS,'*',$whr,'','','');
		$assessment_qustion_details = $callConfig->getAllRows($query);
		$maxoptions = 0;
		foreach ($assessment_qustion_details as $value) {
			$detailoptions = array();
			$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$get['assessment_id']." and question_id=".$value->id;
			$query_ans=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTION_OPTIONS,'*',$whr,'','','');
			$assessment_answer_details = $callConfig->getRow($query_ans);
			$details['question_id'][$value->id] = $value->id;
			$details['assessment_question'][$value->id] = $value->assessment_question;
			$qtype = $value->options_display_type;
			if($qtype==$Qtypes['MultilpleChoice'] || $qtype==$Qtypes['CheckboxQuestion']){
				$detailoptions = json_decode($assessment_answer_details->assessment_question_option,1);
			}
			else{
				$freetext = json_decode($assessment_answer_details->assessment_question_option,1)[0];
				$detailoptions[] = "Remarks";
			}
			$optionid = 0;
			$maxoptions = count((array)$detailoptions) > $maxoptions ? count((array)$detailoptions) : $maxoptions;
			foreach($detailoptions as $optionsdata) { 
				$details['option'][$value->id]['option'][] = $optionsdata;
				$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$get['assessment_id']." and question_id=".$value->id;
				$query_opt=$callConfig->selectQuery(TBL_ASSESSMENT_RESPONSE_DETAILS,'*',$whr,'','','');
				$query_opt_details = $callConfig->getAllRows($query_opt);
				$count=0;
				if($qtype!=4){
					foreach($query_opt_details as $opt){ 
						$response = json_decode($opt->response_option,1); 
						if(in_array($optionsdata, (array)$response)){
							$count = $count+1;;
						}else{
							$count=0;
						}
					}
				}else{
					foreach($query_opt_details as $opt){ 
						$response = json_decode($opt->response_option,1)[0]; 
						if($response!=''){
							$count = $count+1;;
						}else{
							$count=0;
						}
					}
				}
				$details['option'][$value->id]['answer'][$optionid] = $count;
				$optionid++;
			}
		}
		$details['maxoptions'] = $maxoptions;
		return $details;
	}
	function getempassessment($get){
		global $callConfig;
		$tag1 = $get['category'] ==1 ?'Assessments' : '';

		$queryresponse = "SELECT assessment_id,current_status,total_score FROM ".TBL_ASSESSMENT_RESPONSES." WHERE is_active=0 and company_id=".$get['company_id']." and category=".$get['category']." and employee_id=".$get['emp_id']; 
		$assessment_list = $callConfig->getAllRows($queryresponse);

		foreach($assessment_list as $list){
			$whr="company_id=".$get['company_id']." and is_active='0' and category=".$get['category']." and id=".$list->assessment_id;
			$query=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP,'*',$whr,'','','');
			$response = $callConfig->getAllRows($query);
			//print_r($response); 

			foreach($response as $svalues){
				$survyidlist[] = $svalues->id;
				$assessmentvalues = array('current_status'=>$list->current_status,'assessment_id'=>$svalues->id,'assessment_name'=>$svalues->assessment_name,'total_score'=>$list->total_score,'assessment_start_date'=>date('d M, Y',strtotime($svalues->assessment_start_date)),'assessment_end_date'=>date('d M, Y',strtotime($svalues->assessment_end_date)));
				$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$svalues->id;
				$questions=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTIONS,'count(id) as totalquestion',$whr,'','','');
				$qresponse = $callConfig->getRow($questions);
				$assessmentvalues['totalquestion'] = $qresponse->totalquestion;
				if($list->current_status == ST_COMPLETE){ 
					$assessmentvalues['completionrate'] = ST_COMPLETE;
					$assessmentvalues['completionratecolor'] = "success";
				}
				else if (date('Y-m-d') > $svalues->assessment_end_date && strtotime($enddatatime = $svalues->assessment_end_date." ".$svalues->assessment_end_time) < strtotime(date('Y-m-d H:i:s'))) {
					$assessmentvalues['completionratecolor'] = "warning"; // Expired
					$assessmentvalues['completionrate'] = ST_INACTIVE;
				}  else {
					$assessmentvalues['completionrate'] = ST_ACTIVE;
					$assessmentvalues['completionratecolor'] = "primary";
				}
				$details['assessment_details'][] = $assessmentvalues;
			}
		}

		$survyidlist = implode(',',(array)$survyidlist);

		$details['summary'][] = array('data'=>count((array)$assessment_list),'name'=>$tag1,'bgcolor'=>'primary');

		$queryresponse = "SELECT count(id) as total_responses, round(sum(duration_taken)/count(id),2) as avg_duration_taken FROM ".TBL_ASSESSMENT_RESPONSES." WHERE employee_id=".$get['emp_id']." and is_active=0 and company_id=".$get['company_id']." and category=".$get['category']." and assessment_id in (".$survyidlist.") and current_status=".ST_COMPLETE; 
		$response = $callConfig->getRow($queryresponse);

		$details['summary'][] = array('data'=>($response->total_responses)==''?'0':($response->total_responses),'name'=>'Complete','bgcolor'=>'success');

		$queryresponse = "SELECT count(id) as partial  FROM ".TBL_ASSESSMENT_RESPONSES." WHERE employee_id=".$get['emp_id']." and is_active=0 and company_id=".$get['company_id']." and category=".$get['category']." and assessment_id in (".$survyidlist.") and current_status=".ST_INPROGRESS; 
		$presponse = $callConfig->getRow($queryresponse);

		$details['summary'][] = array('data'=>$presponse->partial==''?'0':$presponse->partial,'name'=>'Partial','bgcolor'=>'warning');

		$details['summary'][] = array('data'=>(count((array)$assessment_list)-$response->total_responses)==''?'0':(count((array)$assessment_list)-$response->total_responses),'name'=>'Incomplete','bgcolor'=>'info');

		$details['summary'][] = array('data'=>$response->avg_duration_taken==''?'0':$response->avg_duration_taken,'name'=>'Avg Time','bgcolor'=>'dark');
		if(count((array)$assessment_list)>0){
			$details['rate']= round($response->total_responses/count((array)$assessment_list) *100 ,2)." %";
		}else{
			$details['rate']= "0 %";
		}
		$whr2="company_id=".$get['company_id']." and is_active='0' and genc_code='ASSESSMENT_QTYPE'";
		$query=$callConfig->selectQuery('general_code_details','genc_detail_code,genc_detail_name',$whr2,'','','');
		$details['qustion_types'] = $callConfig->getAllRows($query);
		foreach($details['qustion_types'] as $qustion_types){
			$qtype[$qustion_types->genc_detail_code] = $qustion_types->genc_detail_name;
			$whr="assessment_id in (".$survyidlist.") and company_id=".$get['company_id']." and is_active='0' and options_display_type='".$qustion_types->genc_detail_code."'";
			$questions=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTIONS,'count(id) as totaltypequestion',$whr,'','','');
			$qresponse = $callConfig->getRow($questions);
			$assessment_qtypes[$qustion_types->genc_detail_name] = $qresponse->totaltypequestion;
		}
		$details['assessment_qtypes'] = $assessment_qtypes;
		return $details;
	}
	/*---------------- Assement End------------------------*/

	function getjobsreport($get) {
		global $callConfig;

		$query="SELECT id,department_name  FROM `departments` WHERE company_id='".$get['company_id']."' and is_active='0'";
		$depts = $callConfig->getAllRows($query);
		foreach($depts as $deptvalues){
			$departments[$deptvalues->id] = $deptvalues->department_name;
		}

		$query="SELECT id,location_name  FROM `locations` WHERE company_id='".$get['company_id']."' and is_active='0'";
		$locs = $callConfig->getAllRows($query);
		foreach($locs as $locvalues){
			$locations[$locvalues->id] = $locvalues->location_name;
		}

		$query="SELECT id,job_title  FROM `job_titles` WHERE company_id='".$get['company_id']."' and is_active='0'";
		$jobtitles = $callConfig->getAllRows($query);
		foreach($jobtitles as $jobvalues){
			$job_titles[$jobvalues->id] = $jobvalues->job_title;
		}

		$query="SELECT id,display_name  FROM `employees` WHERE company_id='".$get['company_id']."' and is_active='0'";
		$emps = $callConfig->getAllRows($query);
		foreach($emps as $empdata){
			$emplist[$empdata->id] = $empdata->display_name;
		}

		$query="SELECT id,name,name_value  FROM `status` WHERE company_id='".$get['company_id']."' and is_active='0'";
		$statusnames = $callConfig->getAllRows($query);
		foreach($statusnames as $stat){
			$statuses[$stat->name_value] = $stat->name;
		}

		$details['departments'] =$departments;
		$details['locations'] =$locations;
		$details['job_titles'] =$job_titles;
		$details['emplist'] =$emplist;
		$details['statuses'] =$statuses;

		$query="SELECT s.name as status,j.current_status as status_code, count(j.current_status) as status_count FROM `job_postings` j, status s WHERE j.company_id='".$get['company_id']."' and j.is_active='0' and j.current_status=s.name_value GROUP by j.current_status";
		$jobresponse = $callConfig->getAllRows($query);
		foreach($jobresponse as $statuses){
			$statuslist['statuslist'][] = $statuses->status;
			$statuslist['status_countlist'][] = $statuses->status_count;
		}

		$query="SELECT d.department_name as department, count(j.department_id) as dept_count FROM `job_postings` j, departments d  WHERE j.company_id='".$get['company_id']."' and j.is_active='0' and j.department_id=d.id GROUP by j.department_id";
		$deptjobresponse = $callConfig->getAllRows($query);
		foreach($deptjobresponse as $depts){
			$statuslist['deptlist'][] = $depts->department;
			$statuslist['dept_countlist'][] = $depts->dept_count;
		}


		$query="SELECT d.location_name as location, count(j.location_id) as dept_count FROM `job_postings` j, locations d  WHERE j.company_id='".$get['company_id']."' and j.is_active='0' and j.location_id=d.id GROUP by j.location_id";
		$locsjobresponse = $callConfig->getAllRows($query);
		foreach($locsjobresponse as $locs){
			$statuslist['loclist'][] = $locs->location;
			$statuslist['loc_countlist'][] = $locs->dept_count;
		}


		$query="SELECT d.display_name as display_name, count(j.recruitment_manager) as hire_count FROM `job_postings` j, employees d  WHERE j.company_id='".$get['company_id']."' and j.is_active='0' and j.recruitment_manager=d.id GROUP by j.recruitment_manager";
		$locsjobresponse = $callConfig->getAllRows($query);
		foreach($locsjobresponse as $locs){
			$statuslist['hirelist'][] = $locs->display_name;
			$statuslist['hire_countlist'][] = $locs->hire_count;
		}


		$query="SELECT d.job_title as job_title, count(j.job_code) as jobtitle_count FROM `job_postings` j, job_titles d  WHERE j.company_id='".$get['company_id']."' and j.is_active='0' and j.job_code=d.id GROUP by j.job_code";
		$locsjobresponse = $callConfig->getAllRows($query);
		foreach($locsjobresponse as $locs){
			$statuslist['jobtitlelist'][] = $locs->job_title;
			$statuslist['jobtitle_countlist'][] = $locs->jobtitle_count;
		}

		$query="SELECT * from job_postings WHERE company_id='".$get['company_id']."' and is_active='0'";
		$response = $callConfig->getAllRows($query);
		foreach($response as $result){
			$job_posting_details[] = $result;
		}
		$details['job_postings'] =$job_posting_details; 
		$details['job_status_report'] = $statuslist;

		return $details;
	}
	
