		function saveperformanceresponse($post,$get){
			global $callConfig;
			$response_details = $post['response_detail_array'];

		//print_r($response_details['performance_response_details']);
			$rowid = $post['response_array']['rowid'];
			unset($post['response_array']['rowid']);
