				$res=$callConfig->insertRecord(TBL_PERFORMANCE_RESPONSES,$post['response_array']);
			} else {
				$res=$callConfig->updateRecord(TBL_PERFORMANCE_RESPONSES,$post['response_array'],'id',$rowid);
