	 		$rdd = $callConfig->getRow($rquery);	
				//echo $rquery."<br>";print_r($rdd);
	 		$recount = $rdd->empter;


	 		$fd['val'] = $actemp-$recount;
	 		$fd['name'] = date('M',strtotime($yy.'-'.$i));
	 		$fd['val2'] = $recount;
	 		$fdd[]=$fd;
	 		$ssdate = date("Y-m-d", strtotime($ssdate."+1 month"));
	 	}
	 	$data['fgraph'] = $fdd;

	 	$pquery = "SELECT pay_month, SUM(gross_pay) as gpay FROM `payroll` WHERE `pay_year`= '".$yy."' GROUP BY pay_month";
	 	$pdata = $callConfig->getAllRows($pquery);
	 	foreach($pdata as $ppdata){
	 		$pr[$ppdata->pay_month]	 = $ppdata->gpay;
	 	}
	 	for ($i=0; $i < 13; $i++) { 

	 		$prdd[$i] = $pr[$i]!="" ? $pr[$i] :'0' ;
	 	}
	 	$data['payroll'] = $prdd;
	 	return $data;
	 }
