function getjobpostingsreport($get) {
	global $callConfig;
	$jobstypes = array('0'=>'Open','2'=>'In-Progress','1'=>'Close','3'=>'Total');
	$sql = "select * from vendors where company_id='".$get['company_id']."' and is_active='0'";
	$vendors = $callConfig->getAllRows($sql);

	$datecondition = "AND (current_date() >= jp.requested_date)";
	if($get['fromdate']!='' || $get['todate']){
		$datecondition = "AND jp.requested_date between '".$get['fromdate']."' and '".$get['todate']."'";
	}
	$queryresponse = "SELECT jpd.vendor_id, jp.current_status, jp.job_status, COUNT(jp.id) as totalcount FROM job_posting_distribute jpd, job_postings jp, job_posting_candidates jpc WHERE jp.id = jpd.job_posting_id AND jp.company_id = jpd.company_id AND jp.is_active = '0' AND jpd.is_active = '0' ".$datecondition." AND jpc.job_posting_id = jp.id AND jpc.company_id = jp.company_id AND jpc.is_active = '0' GROUP BY jpd.vendor_id, jp.current_status,jp.job_status"; 
	$allresponse = $callConfig->getAllRows($queryresponse);
	$total =0;
	foreach($jobstypes as $jobkey=>$jobtype) {
		$job_type_total =0;
		foreach($allresponse as $data){
			if($data->job_status==$jobkey){
				$job_type_total += $data->totalcount;
				$total += $data->totalcount;
			}
		}
		$job_type_array[$jobkey] = $job_type_total;
	}
	$job_type_array[3] = $total;			
	foreach($allresponse as $data){
		foreach($jobstypes as $jobkey=>$jobtype){
			foreach($vendors as $ven){
				if($ven->id==$data->vendor_id && $jobkey==$data->job_status){
					$vendor_jobs[$ven->id][$jobkey] = $data->totalcount;
				}
			}

		}
	}
	foreach($vendor_jobs as $vid=>$vjobs){
		$totalj=0;
		foreach($vjobs as $jobcount){
			$totalj +=$jobcount;
		}
		$vendor_jobs[$vid][3] = $totalj;
	}
	$details['summary']=$job_type_array;
	$details['job_type_data']=$jobstypes;
	$details['vendor_jobs']=$vendor_jobs;
		//echo "<pre>"; print_r($details);exit;
	return $details;
}

function insertseriallot($post,$get){
	global $callConfig;
	echo "ravi"; print_r($post);
	if($post['type']==1){
		if($post['tranid']!="" && $post['tranid']!=0 ){
			$query = "UPDATE item_serial_nos SET is_active='1' WHERE transaction_id =".$post['tranid']." AND transaction_table='".$post['table']."' AND item_id=".$post['item_id'] ;
					//echo $query;
			$upp = $callConfig->executeQuery($query);
		}else{
			$random = $post['random'];
		}
		for($i=1; $i<$post['count']+1; $i++){
			$serial ='serial_'.$i;
			$notdataa = array('company_id'=>$get['company_id'], 'transaction_id'=>$post['tranid'], 'transaction_table'=>$post['table'], 'random_no'=>$random, 'item_id'=>$post['item_id'], 'serial_no'=>$post[$serial],'is_active'=>'0','current_status'=>0,'created_by'=>$get['user_id'],'created_date'=>date('Y-m-d H:i:s'));
					//print_r($notdataa);
			$insert[] = $callConfig->insertRecord('item_serial_nos',$notdataa);
		}
	}
	if($post['type']==2){
		if($post['tranid']!="" && $post['tranid']!=0){
			$query = "UPDATE item_lot_nos SET is_active='1' WHERE transaction_id =".$post['tranid']." AND transaction_table='".$post['table']."' AND item_id=".$post['item_id'] ;
					//echo $query;
			$upp = $callConfig->executeQuery($query);
		}else{
			$random = $post['random'];
		}
		for($i=1; $i<$post['count']+1; $i++){
			$lot ='lot_'.$i;
			$lotvalue ='lotvalue_'.$i;
			$notdataa = array('company_id'=>$get['company_id'], 'transaction_id'=>$post['tranid'], 'transaction_table'=>$post['table'], 'random_no'=>$random, 'item_id'=>$post['item_id'], 'lot_no'=>$post[$lot],'lot_quantity'=>$post[$lotvalue],'is_active'=>'0','current_status'=>0,'created_by'=>$get['user_id'],'created_date'=>date('Y-m-d H:i:s'));
					//print_r($notdataa);
			$insert[] = $callConfig->insertRecord('item_lot_nos',$notdataa);
		}
	}
	return array('query'=>$notdataa,'res'=>$insert);
}
