function insertEmpHistries($data){
	global $callConfig;
	unset($data['page']);
	unset($data['user_id']);
	$user_id = $data['user_id'];
	if($data['field_name']=="on_off_site"){ 
		$arrayinserte = array("on_off_site"=>$data['field_value']); 
	}elseif($data['field_name']=="work_from_home"){ 
		$arrayinserte = array("work_from_home"=>$data['field_value']); 
	}else{
		$arrayinserte = array("billable"=>$data['field_value']); 
	}
	$where = "id = '".$data['emp_id']."'";
	$res=$callConfig->updateRecord("employees",$arrayinserte,"","",$where);
	$csdcdfv['emp'] = $res;
	$data['effective_from'] = $this->dateconvertdbformat($data['effective_from']);
	$data['effective_to'] = $this->dateconvertdbformat($data['effective_to']);
	$data['created_date'] = date("Y-m-d H:i:s");
	$data['created_by'] = $user_id;
	$ress=$callConfig->insertRecord('emp_histories',$data);
	$csdcdfv['history'] = $ress;
	return $csdcdfv;
}


	
	
