		if($data['interviewer_check']=="interviewer"){
			$notdataa['notification_message'] = "This Candidate(".$data['job_posing_candidate_id'].") interview is schudule at".$data['inerview_date_time'];
			$notdataa['notification_users'] = array($data['assign_id']);
			$this->tosendnotifiations($notdataa);
		}

		return $res;
	}
