	function getApplicationRole($get){
		global $callConfig;
		$application_rolessql = "SELECT * FROM application_roles WHERE company_id='".$get['company_id']."' AND id='".$get['application_roles']."' AND is_active = 0";
		$application_rolesres=$callConfig->getRow($application_rolessql);
		$return['application_roles'] = $application_rolesres;
		$moduleid = $application_rolesres->application_module !=""?$application_rolesres->application_module:$get['selectmodule_id'];

		// $allapplication_rolessql = "SELECT role_short_code FROM application_roles WHERE company_id='".$get['company_id']."' AND is_active = 0";
		// $allapplication_rolesres=$callConfig->getAllRows($allapplication_rolessql);
		// $return['all_application_roles'] = $allapplication_rolesres;


		$menulocationsql = "SELECT genc_detail_code, genc_detail_name FROM general_code_details WHERE company_id='".$get['company_id']."' AND genc_code='MENULOCATION' AND is_active = 0";
		$menulocationres=$callConfig->getAllRows($menulocationsql);
		$return['menulocation'] = $menulocationres;


		$module_setupsql = "SELECT module_id, display_name FROM module_setup WHERE company_id='".$get['company_id']."' AND module_id = '".$moduleid."' AND is_active = 0";
		$module_setupres=$callConfig->getRow($module_setupsql);
		$return['module_setup'] = $module_setupres;

		$application_process_rolesql = "SELECT application_process_id,id,is_active FROM `application_process_role` WHERE role_short_code = '".$application_rolesres->role_short_code."' AND company_id = '".$get['company_id']."' and is_active = 0 ";
		$application_process_roleres=$callConfig->getAllRows($application_process_rolesql);
		$return['application_process_role'] = $application_process_roleres;


		$application_processsql = "SELECT id,module_setup_id,process_name,short_code FROM `application_process` WHERE module_setup_id = '".$moduleid."' AND company_id = '".$get['company_id']."' and is_active = 0";
		$application_processres=$callConfig->getAllRows($application_processsql);
		$return['application_process'] = $application_processres;

		foreach($application_process_roleres as $resutlvalue){
			if($resutlvalue->is_active==0){
				$processseleclis[] = $resutlvalue->application_process_id;
			}
		}

		$lists = implode(",",(array)$processseleclis);
		$application_process_pagessql = "SELECT * FROM `application_process_pages` WHERE company_id = '".$get['company_id']."' and is_active = 0 AND application_process_id in(".$lists.") order by display_priority ASC";
		$application_process_pagesres=$callConfig->getAllRows($application_process_pagessql);
		$return['application_process_pages'] = $application_process_pagesres;

		$role_permissionssql = "SELECT `table_name`, `page_name`, `application_process_page_id`, `permission_view`, `permission_insert`, `permission_update`, `permission_delete`, `permission_print`, `permission_import`, `permission_export`, `permission_download`, `role_id`, `role_short_code` FROM `role_permissions` WHERE company_id = '".$get['company_id']."' AND role_short_code = '".$application_rolesres->role_short_code."' and is_active = 0";
		$role_permissionsres=$callConfig->getAllRows($role_permissionssql);
		$return['role_permissions'] = $role_permissionsres;


		return $return;	
	}
	function insertRole($data){
		global $callConfig;
		$returnarray['data']  = $data;
		$role_id = $data['role_id'];
		$role_short_code = $data['role_short_code'];
		$roletable['company_id']=$data['company_id'];
		$roletable['application_module']=$data['application_module'];
		$roletable['current_status']='0';
		$roletable['is_active']='0';
		$roletable['display_name']=$data['role_name'];
		$roletable['name']=$data['role_name'];
		$roletable['description']=$data['role_name'];
		$roletable['role_short_code']=$role_short_code;
		$roletable['view_nav']=json_encode($data['menulocation']);
		if($role_id!= ""){
			$roletable['updated_date']=date('Y-m-d H:i:s');
			$roletable['updated_by']=$data['user_id'];
			$res=$callConfig->updateRecord('application_roles',$roletable,'id',$data['role_id']);
			$returnarray['application_roles_update'] = $res;
		}else{
			$roletable['created_date']=date('Y-m-d H:i:s');
			$roletable['created_By']=$data['user_id'];
			$res = $callConfig->insertRecord("application_roles",$roletable);
			$role_id = $res['LASTID'];
			$returnarray['application_roles_insert'] = $res;
		}
		$sdcdfc['is_active']='1';
		$sdcdfc['updated_date']=date('Y-m-d H:i:s');
		$sdcdfc['updated_by']=$data['user_id'];
		$cddc=$callConfig->updateRecord('application_process_role',$sdcdfc,'application_role_id',$role_id);
		$returnarray['application_process_role_update'][] = $cddc;
		foreach($data['permision'] as $value){
			$permision['company_id']=$data['company_id'];
			$permision['application_role_id']=$role_id;
			$permision['role_short_code']=$role_short_code;
			$permision['current_status']='0';  
			$permision['application_process_id']=$value;
			$permision['is_active']='0';
			$permision['created_date']=date('Y-m-d H:i:s');
			$permision['created_By']=$data['user_id'];
			$resss = $callConfig->insertRecord("application_process_role",$permision);
			$returnarray['application_process_role_insert'][] = $resss;
		}
		$st['is_active']='1';
		$st['Updated_By']=$data['user_id'];
		$st['Updated_Date']=date('Y-m-d H:i:s');
		$roleupdate=$callConfig->updateRecord('role_permissions',$st,'role_id',$role_id);
		$returnarray['role_permissions_update'][] = $roleupdate;
		foreach($data['processname'] as $key=>$value){
			$process1['company_id']=$data['company_id'];
			$process1['role_id']=$role_id;
			$process1['role_short_code']=$role_short_code;
			$process1['is_active']='0';
			$process1['permission_delete']='0';
			$process1['Current_Status']='0';
			$process1['table_name']=$data['processtablename'][$key];
			$process1['page_name']=$value;
			$process1['Created_Date']=date('Y-m-d H:i:s');
			$process1['Created_By']=$data['user_id'];
			$process1['application_process_page_id']=$data['processpageid'][$key];
			$process1['permission_view']=isset($data['pageslistread'][$key])?'0':'1';
			$process1['permission_insert']=isset($data['pageslistwrite'][$key])?'0':'1';
			$process1['permission_update']=isset($data['pageslistcreate'][$key])?'0':'1';
			$process1['permission_delete']=isset($data['pageslistdelete'][$key])?'0':'1';
			$process1['permission_print']=isset($data['pageslistprint'][$key])?'0':'1';
			$process1['permission_import']=isset($data['pageslistimport'][$key])?'0':'1';
			$process1['permission_export']=isset($data['pageslistexport'][$key])?'0':'1';
			$process1['permission_download']=isset($data['pageslistdownload'][$key])?'0':'1';
			$process1['permission_approval']=isset($data['pageslistapproval'][$key])?'0':'1';
			$process1['permission_analytic']=isset($data['pageslistanalytic'][$key])?'0':'1';
			$checksql = "SELECT id FROM `role_permissions` WHERE company_id = '".$data['company_id']."' and table_name ='".$data['processtablename'][$key]."' and page_name = '".$value."' and application_process_page_id = '".$data['processpageid'][$key]."' and role_id = '".$role_id."'";
			$checksqldetails=$callConfig->getRow($checksql);
			$returnarray['role_permissions_id'][] = $checksqldetails;
			if(isset($checksqldetails->id)){
				$resssscd=$callConfig->updateRecord('role_permissions',$process1,'id',$checksqldetails->id);
				$returnarray['role_permissions_update'][] = $resssscd;
			}else{
				$resssscd = $callConfig->insertRecord("role_permissions",$process1);
				$returnarray['role_permissions_insert'][] = $resssscd;
			}
		}

		return $returnarray;
	}
