	function getDyanamicAutoSelectData($table_name, $filed_name,$words){
		global $callConfig;
		$whr = "application_table_name= '".$table_name."' AND field_name = '".$filed_name."'";
		$query=$callConfig->selectQuery(TBL_DISPLAYATTRIBUTES_TYPE,'*',$whr,'','','');
		$data = $callConfig->getRow($query);
		$display = $data->display_field;
		$value = $data->value_field;
		$array['type'] = $data->attribute_type;
		if($data->attribute_type == 'custom_sql'){
			$qquery = urldecode($data->content);
			if(strpos($qquery,'WHERE')){
				$cwhr = "AND company_id=".$data->company_id." AND ".$display." like '%".$words."%'  ORDER BY";
			}else{
				$cwhr = "WHERE company_id=".$data->company_id." AND ".$display." like '%".$words."%' ORDER BY";
			}
			$qquery = str_replace('ORDER BY', $cwhr, $qquery);
			$qquery .= " limit 20";
			$custom_sql = $callConfig->getAllRows($qquery);
			foreach ($custom_sql as $custom){
				$array1[] =  array('id'=>$custom->$value,'full_name'=>$custom->$display);
			}
		}else{
			$$array1['res'] = json_decode($data->content,1);
		}
		return $array1;
	}
	function getcitydatasautotype($data){
		global $callConfig;
		if($data['extracat'] !=""){
			$attchsql = ", ".$data['extracat'];
		}
		if($data['transaction_date'] !="" AND $data['table'] = 'items'){
			$extraconditon = " AND (from_date <='".$this->dateconvertdbformat($data['transaction_date'])."' AND to_date >= '".$this->dateconvertdbformat($data['transaction_date'])."' OR from_date IS NULL)";
		}
		if($data['table'] == 'chart_of_accounts'){
			$extraconditon = " AND allow_posting = 0 ";
		}
		if(isset($data['selectvalue'])){
			if($data['table']=='items'){
				$sql = "SELECT id, ".$data['selectfiled'].$attchsql.", sku FROM ".$data['table']." WHERE company_id = '".$data['company_id']."' AND (".$data['selectfiled']." like '%".$data['namewords']."%' OR sku like '%".$data['namewords']."%') and id NOT IN (".$data['selectvalue'].") ".$extraconditon." LIMIT 10";
			}else{
				$sql = "SELECT id, ".$data['selectfiled'].$attchsql." FROM ".$data['table']." WHERE company_id = '".$data['company_id']."' AND ".$data['selectfiled']." like '%".$data['namewords']."%' and id NOT IN (".$data['selectvalue'].") ".$extraconditon." LIMIT 10";
						
			}
			
		}else{
			if($data['table']=='items'){
				$sql = "SELECT id,".$data['selectfiled'].$attchsql.", sku FROM ".$data['table']." WHERE company_id = '".$data['company_id']."' AND (".$data['selectfiled']." like '%".$data['namewords']."%' OR sku like '%".$data['namewords']."%') ".$extraconditon." LIMIT 10";
			}else{
				$sql = "SELECT id,".$data['selectfiled'].$attchsql." FROM ".$data['table']." WHERE company_id = '".$data['company_id']."' AND ".$data['selectfiled']." like '%".$data['namewords']."%' ".$extraconditon." LIMIT 10";
			}
		}
		//echo $sql;
		$reviewdata=$callConfig->getAllRows($sql);
		return $reviewdata;
	}
