	function toreusetracking($table,$trn){
		global $callConfig;
		$query = "select * from ".$table ." WHERE id=".$trn;
		//echo $query;
		$row = $callConfig->getRow($query);
		//print_r($row);
		if($table=="bill_payments"){
			$return['table'] = $table;
			$return['trn_no'] = $row->id;
			$return['trn_id'] = $trn;
			$return['trn_date'] = $row->payment_date;
			$return['ref_table'] ="bills";
			$return['ref_trn_no'] = "";
			$return['ref_trn_id'] = $row->bill_id;
			$return['ref_trn_date'] = "";
			$return['user_id'] = $row->created_by;			
		}else{
			$return['table'] = $table;
			$return['trn_no'] = $row->transaction_number;
			$return['trn_id'] = $trn;
			$return['trn_date'] = $row->transaction_date;
			$return['ref_table'] = $row->ref_type;
			$return['ref_trn_no'] = $row->ref_no;
			$return['ref_trn_id'] = $row->ref_id;
			$return['ref_trn_date'] = $row->ref_date;
			$return['user_id'] = $row->created_by;
		}
		return $return;
	}
	function candidatesofferhistories($data){
		global $callConfig;
		$sql = "SELECT id,annual_ctc from salary_template where candidate_id='".$data['candidate_id']."' AND company_id = '".$data['company_id']."' and is_active = 0";	
