	function insertReportAttributesNew($data){
		global $callConfig;
		if($data['report_id']!=""){
			$where = "id = '".$data['report_id']."'";
			$data['updated_by']= $data['user_id'];
			$data['updated_date'] = date('Y-m-d H:i:s');
			unset($data['user_id']);
			unset($data['report_id']);
			unset($data['module_id']);
			unset($data['module_group_id']);			
			$res=$callConfig->updateRecord("report_attributes",$data,"","",$where);
		}else{
			unset($data['module_id']);
			unset($data['module_group_id']);
			unset($data['report_id']);
			$data['created_by']= $data['user_id'];
			$data['created_date'] = date('Y-m-d H:i:s');
			unset($data['user_id']);			
			$transation = $this->toGetApplicationSerialNumber('report_attributes');
			$data['report_code'] = $transation;
			$res=$callConfig->insertRecord("report_attributes",$data);	
		}
		return $res;
	}
	function getMyReportfields($get){
		global $callConfig;
		$sqlbuild = ""; 
		$returnarray = array();
		$reportsql = "SELECT * FROM report_attributes WHERE id = '".$get['Rid']."' AND is_active =0 AND company_id = '".$get['company_id']."'";
		$reportres=$callConfig->getRow($reportsql);
		$sqlbuild = urldecode($reportres->content);
		$decode_reportres = json_decode(urldecode($reportres->content_details),1);
		//$returnarray['content_details'] = $decode_reportres;
		$formulaplaceholder  = $decode_reportres['formulaplaceholder'];
		foreach($formulaplaceholder as $key=>$formulaplaceholders){
			$placename = explode("@", $key);
			$sqlbuild = str_replace ($key, '('.$formulaplaceholders.') as '.$placename[1], $sqlbuild);
			//$returnarray['filed'][] = ".".$placename[1];
			$returnarray['filed'][] = $placename[1];
		}
		foreach($decode_reportres['tablefiledsselect'] as $tbalnamekey=>$selectfileds){
			foreach ($selectfileds as $keyee => $valuee) {
				$returnarray['filed'][] = $valuee;
			}	
		}
		foreach($decode_reportres['selectedtables'] as $selectedtables){
			$display_data = "select id,list_attributes from ".TBL_DISPLAYATTRIBUTES." where application_table_name='".$selectedtables."' and company_id='".$get['company_id']."'"; 
			$list_attribute = $callConfig->getRow($display_data);
			$returnarray['display_attributes'][$selectedtables] =  json_decode($list_attribute->list_attributes,1);
		}

		//echo $sqlbuild;
		$return_res=$callConfig->getRow($sqlbuild);
		$returnarray['reportattributesfields'] = $return_res;
		$myreportsql = "SELECT * FROM my_reports WHERE report_id = '".$get['Rid']."' AND is_active =0 AND company_id = '".$get['company_id']."'";
		$myreportres=$callConfig->getRow($myreportsql);
		$returnarray['my_report'] = $myreportres;

		$module_setupsql = "SELECT module_id, module_name FROM module_setup WHERE company_id = '".$get['company_id']."' AND is_active =0";
		$module_setupres=$callConfig->getAllRows($module_setupsql);
		$returnarray['module_setup'] = $module_setupres;

		return $returnarray;
		
	}
	function myreportViewSql($data){
		global $callConfig;
		$sessionarrays = json_decode($data['sessionarrays'],1);
		$dynamicsql ="";
		$myreportsql = "SELECT report_list FROM my_reports WHERE report_id = '".$data['rid']."' AND is_active =0 AND company_id = '".$data['company_id']."'";
		$myreportresult=$callConfig->getRow($myreportsql);
		$decode_myreportresult1 = json_decode(urldecode($myreportresult->report_list),1);
		$filtertype = array();
		foreach($decode_myreportresult1 as $decode_myreportresult){
			if($decode_myreportresult['switch'] == '0'){
				$filtertype[$decode_myreportresult['feildname']] = $decode_myreportresult['filtertype'];
				$filterkey[$decode_myreportresult['feildname']] = $decode_myreportresult['tablenames'].".".$decode_myreportresult['displayfeildname'];
			}
		}
		$return['filter'] = $decode_myreportresult1;
		$whr = json_decode($data['where'],1);
		$whr = $whr['where'];
		if($whr !=''){
			foreach ($whr as $key => $value) {
				if(isset($filtertype[$key])){
					if($filtertype[$key] == "select"){
						$where.= $filterkey[$key]." = '".$value."' AND ";
					}elseif($filtertype[$key] == "year"){
						$month = explode('-', $value);
						$where.= "YEAR(".$filterkey[$key].") = '".$month[0]."' AND ";
					}elseif($filtertype[$key] == "month"){
						$month = explode('-', $value);
						$where.= "MONTH(".$filterkey[$key].") = '".$month[1]."' AND ";
					}elseif($filtertype[$key] == "date_pick"){
						$where.= $filterkey[$key]." >= '".$this->dateconvertdbformat($value[0])."' AND ".$filterkey[$key]." <= '".$this->dateconvertdbformat($value[1])."' AND ";
					}elseif($filtertype[$key] == "month_year"){
						$month = explode('-', $value);
						$where.= "MONTH(".$filterkey[$key].") = '".$month[0]."' AND YEAR(".$filterkey[$key].") = '".$month[1]."'";
					}else{
						$where.= $filterkey[$key]." like '%".$value."%' AND ";
					}
				}		
			}
			$where = trim($where,'AND ');
		}
		$reportsql = "SELECT * FROM report_attributes WHERE id = '".$data['rid']."' AND is_active =0 AND company_id = '".$data['company_id']."'";
		$reportres=$callConfig->getRow($reportsql);
		$sqlbuild = urldecode($reportres->content);
		$decode_reportres = json_decode(urldecode($reportres->content_details),1);
		$formulaplaceholder  = $decode_reportres['formulaplaceholder'];
		$formquery = (explode("FROM",$sqlbuild));
		$querywhere = (explode("WHERE",$sqlbuild));
		$querorderby = (explode("ORDER BY",$formquery[1]));
		$quergroupby = (explode("GROUP BY",$formquery[1]));
		if(isset($quergroupby[1])){
			$formquery[1] = $quergroupby[0];
			$orderby = " GROUP BY".$quergroupby[1];	
		}else{
			if(isset($querorderby[1])){
				$formquery[1] = $querorderby[0];
				$orderby = " ORDER BY".$querorderby[1];
			}
		}
		if(isset($querywhere[1])){
			if($where !=""){
				$sqlbuild = $formquery[0]." FROM ".$formquery[1]." AND ".$where." ".$orderby;
			}else{
				$sqlbuild = $formquery[0]." FROM ".$formquery[1]." ".$orderby;
			}
		}else{
			if($where !=""){
				$sqlbuild = $formquery[0]." FROM ".$formquery[1]." WHERE ".$where." ".$orderby;
			}else{
				$sqlbuild = $formquery[0]." FROM ".$formquery[1]." ".$orderby;
			}
		}
		foreach($formulaplaceholder as $key=>$formulaplaceholders){
			$placename = explode("@", $key);
			$sqlbuild = str_replace ($key, '('.$formulaplaceholders.') as '.$placename[1], $sqlbuild);
		}
		
		foreach($sessionarrays as $keyy=>$sessionarray){
			//$placename = explode("#", $keyy);
			$sqlbuild = str_replace ("#".$keyy, $sessionarray, $sqlbuild);
		}
		$return_res=$callConfig->getAllRows($sqlbuild);
		$return['sql'] = $sqlbuild;
		$return['result'] = $return_res;
		return $return;
	}



	function reportFilterSelectData($data){
		global $callConfig;
		$whr = "report_id= '".$data['report_id']."' AND field_name = '".$data['filed_name']."'";
		$query=$callConfig->selectQuery('report_filters','*',$whr,'','','');
		$data = $callConfig->getRow($query);
		$display = $data->display_field;
		$value = $data->value_field;
		$array['type'] = 'custom_sql';
		if($data->filter_type == 'custom_sql'){
			$qquery = urldecode($data->content);
			if(strpos($qquery,'WHERE')){
				$cwhr = "AND company_id=".$data->company_id." ORDER BY";
			}else{
				$cwhr = "WHERE company_id=".$data->company_id." ORDER BY";
			}
			$qquery = str_replace('ORDER BY', $cwhr, $qquery);
			$custom_sql = $callConfig->getAllRows($qquery);
			foreach ($custom_sql as $custom){
				$array1[$custom->$value] = $custom->$display;
			}
			$array['res'] = $array1;
		}else{
			$array['res'] = json_decode($data->content,1);
		}
		return $array;
	}
