	function checkWhoShouldApproves($data){

		global $callConfig;
		$checkcriteria = $this->checkCriteria($data);
	//print_r($checkcriteria);

		if(isset($checkcriteria['workflow_configuration'])){

		//print_r($checkcriteria);
		//print_r("dfdfv");
//print_r($checkcriteria['workflow_configuration']->approval_type);
		//$step = ($checkcriteria['workflow_configuration']->approval_order !="" AND $checkcriteria['workflow_configuration']->approval_order =='S')?1:"";
		//echo $checkcriteria['workflow_configuration']->approval_type;
			$step ="";
			if($checkcriteria['workflow_configuration']->approval_type == 'manager'){
				$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['user_id']."'";  // table name and exicution type creation and update
				$rowd = $callConfig->getRow($sql); //reports_to
				$row['reports_to']  = $rowd->reports_to;
		//	$row['reports_to']  = $data['user_id'];
				$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);

			}elseif($checkcriteria['workflow_configuration']->approval_type == 'Managers_Manager'){
				$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['user_id']."'";
			$rows = $callConfig->getRow($sql); //manager
			$sql1 = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$rows->reports_to."'";
			$row1 = $callConfig->getRow($sql1); //managers manager
			$row['reports_to']  = $row1->reports_to;
			$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'user'){
			$row['reports_to']  = $checkcriteria['workflow_configuration']->sub_approve_type;
			$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
			// echo "user work";
			// print_r($checkalready);
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'custom_process'){
			$conjson = json_decode($checkcriteria['workflow_configuration']->sub_approve_type,1);
			$m = 1;
			$step = 1;
			foreach($conjson as $ro){
				$row['reports_to']  = $ro['step_'.$m];
				if($step == '1' and $m==1){  //seqquencial
					$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
				}
				if($step == ""){   //pareler 
					$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
				}
				$m++;
			}
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'access_levels'){
			$like = "'".'%"'.$checkcriteria['workflow_configuration']->sub_approve_type.'"%'."'";
			$sql = "SELECT id FROM `application_users` WHERE  is_active = 0 AND company_id = '".$data['company_id']."' AND role_id like ".$like;
			$row=$callConfig->getAllRows($sql);
			$i=1;
			foreach($row as $ro){
				$row['reports_to']  = $ro->id;
				if($step == '1' and $i==1){
					$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
				}
				if($step == ""){
					$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
				}
				$i++;
			}
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'role_levels'){
			
			$getuserid =$this->rolelevelworkflow($checkcriteria,$data,1);
			$row['reports_to']  = $getuserid;
			$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);

		}elseif($checkcriteria['workflow_configuration']->approval_type == 'user_hierarchical'){
			$reportid = '';
			//echo $step;
			$step = 1;
			for($i=1;$i <= $step; $i++){ 	
				if($i==1){
					$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['user_id']."'";
					$rows=$callConfig->getRow($sql);
					$reportid  = $rows->reports_to;
				}else{
					$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$reportid."'";
					$rows=$callConfig->getRow($sql);
					$reportid  = $rows->reports_to;
				}
				$row['reports_to']  = $reportid;
				$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
			}
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'buddy'){
			$row['reports_to']  = $this->findbuddyid($checkcriteria,$data);
			$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'individual_employee_role'){
			$empdata = "select user_id from employees where role_id=".$checkcriteria['workflow_configuration']->sub_approve_type." and is_active='0' and company_id = '".$data['company_id']."'"; 
			$rows=$callConfig->getRow($empdata);
			$row['reports_to']  = $rows->user_id;
			$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'email_groups'){
			$emailgroup = "SELECT e.user_id FROM `email_group_emails` ege left JOIN email e on ege.email_id=e.id WHERE ege.email_groups_id =".$checkcriteria['workflow_configuration']->sub_approve_type." and ege.is_active='0' and ege.company_id = '".$data['company_id']."' "; 
			$emailgrouprows=$callConfig->getAllRows($emailgroup);
			foreach($emailgrouprows as $emailgrouprows){
				$row['reports_to']  = $emailgrouprows->user_id;
				$checkalready = $this->checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row);
			}
		}
		return array("status"=>$rows);
	}else{
		return 